		h--
	} else {
		mn = m1 - m
	}

	if n1 < n {
		n1 = 24 + n1
	}

	h += (n1-n)*60 + mn

	md := (h / 2) / 60
	mx := h/2 - md*60

	if n+md+1 < 10 {
		fmt.Print(0)
	}

	fmt.Println(mx, m)
