func main() {
	stdin := readStdIn()
	nums := convertToInts(stdin)

	w1 := nums[0]
	h1 := nums[1]
	w2 := nums[2]
	h2 := nums[3]

	sum := 0

	sum += w1 + 2
	for j := 1; j <= h2; j++ {
		sum += 2
	}

	sum += w1 - w2 + 2
	for i := 1; i <= h1; i++ {
		sum += w1 + 2
	}
	sum += w1 + 2
	fmt.Println(sum)
}

func readStdIn() string {
	r := bufio.NewReader(os.Stdin)
	text, err := r.ReadString('\n')
	if err != nil {
		panic(err)
	}
	return strings.TrimSpace(text)
}

func convertToInts(str string) []int {
	tokens := strings.Split(str, " ")
	nums := make([]int, 0, len(tokens))
	for _, t := range tokens {
		n, _ := strconv.Atoi(t)
		nums = append(nums, n)
	}
	return nums
}

