func winpos(table [][]byte, sx, sy, dx, dy int) bool {
	x, y := sx, sy
	i := 0
	for i < 5 {
	    if  x>=10 || y>=10 {
	        return false
	    }

		if table[x][y]!='X' {
			return false
		}

		x += dx
		y += dy

		i++
	}

	return true
}

func win(table [][]byte) bool {
	for i := 0; i < 10; i++ {
		for j := 0;j < 10; j++ {
			if winpos(table, i, j, 0, 1) || winpos(table, i, j, 1, 0) || winpos(table, i, j, 1, 1) {
				return true 
			}
		}
	}

	return false
}

func main() {
    stdin := bufio.NewReader(os.Stdin)
	table := make([][]byte,  10)
	for i := 0; i < 10; i++ {
		table[i], _, _ = stdin.ReadLine()

	}

	for i := 0; i < 10; i++ {
		for j := 0;j < 10; j++ {
			if table[i][j]=='.' {
				table[i][j]='X'
				if win(table) {
					fmt.Println("YES")
					os.Exit(0)
				}

				table[i][j]='.'
			}
		}
	}

	fmt.Println("NO")
	os.Exit(0)
}

