func intersect(l1 int, r1 int, l2 int, r2 int) bool {
    if l1 > r1 {
        l1, r1 = r1, l1
    }
    if l2 > r2 {
        l2, r2 = r2, l2
    }
    return l1 < l2  && l2 < r1 && r1 < r2 || l2 < l1 && l1 < r2 && r2 < r1
}

