type move struct {
	x  int
	y  int
	dx int
	dy int
	w  int
}

const W = 5000 * 1000
const H = 5*30*2 + 10
const Z = H / 2

var used [H][H][3][3]bool
var wave [H][H][3][3]int
var t [31]int
var n int

var q [W]move
var hd, tl int

func push(m move) {
	q[tl] = m
	if tl == W-1 {
		tl = 0
	} else {
		tl += 1
	}
}

func pop() move {
	ret := q[hd]
	if hd == W-1 {
		hd = 0
	} else {
		hd += 1
	}
	return ret
}

func empty() bool {
	return hd == tl
}

var ndx [3][3]int
var ndy [3][3]int
var ndxx [3][3]int
var ndyy [3][3]int

func do() {
	m := pop()

	tt := t[m.w]
	lx := m.x + (tt-1)*m.dx
	ly := m.y + (tt-1)*m.dy

	//fmt.Printf("%d lines from (%d, %d) with dir (%d, %d)\n", tt, m.x-Z, m.y-Z, m.dx, m.dy)

	for i := 0; i < tt; i++ {
		used[m.x+i*m.dx][m.y+i*m.dy][1+m.dx][1+m.dy] = true
	}
	wave[m.x][m.y][1+m.dx][1+m.dy] = m.w

	if m.w+1 < n {
		ndx1 := ndx[1+m.dx][1+m.dy]
		ndy1 := ndy[1+m.dx][1+m.dy]
		x1 := lx + ndx1
		y1 := ly + ndy1
		if wave[x1][y1][1+ndx1][1+ndy1] < m.w+1 {
			push(move{x1, y1, ndx1, ndy1, m.w + 1})
		}

		ndx2 := ndxx[1+m.dx][1+m.dy]
		ndy2 := ndyy[1+m.dx][1+m.dy]
		x2 := lx + ndx2
		y2 := ly + ndy2
		if wave[x2][y2][1+ndx2][1+ndy2] < m.w+1 {
			push(move{x2, y2, ndx2, ndy2, m.w + 1})
		}
	}
}

