	for x := 0; x < H; x++ {
		for y := 0; y < H; y++ {
			for i := 0; i < 3; i++ {
				for j := 0; j < 3; j++ {
					wave[x][y][i][j] = -1
					used[x][y][i][j] = false
				}
			}
		}
	}

	push(move{Z, Z, 0, 1, 0})

	for !empty() {
		do()
	}

	ret := 0
	for x := 0; x < H; x++ {
		for y := 0; y < H; y++ {
			fg := false
