	return len(s)
}

func need_array(input1 string, input2 string) bool {
	if len(input1) != len(input2) {
		return false
	}

	input1Bytes := []rune(input1)
	input2Bytes := []rune(input2)

	sort.Sort(sortRunes(input1Bytes))
	sort.Sort(sortRunes(input2Bytes))

	for i := 0; i < len(input1Bytes); i++ {
		if input1Bytes[i] != input2Bytes[i] {
			return false
		}
	}

	return true
}

func need_both(input1 string, input2 string) bool {
	input1Bytes := []rune(input1)
	input2Bytes := []rune(input2)

	sort.Sort(sortRunes(input1Bytes))
	sort.Sort(sortRunes(input2Bytes))

	if len(input2Bytes) > len(input1Bytes) {
		return false
	}

	i, j := 0, 0

	for {
		if i >= len(input2Bytes) || j >= len(input1Bytes) {
			break
		}

		if input2Bytes[i] == input1Bytes[j] {
			i++
			j++
		} else if input2Bytes[i] > input1Bytes[j] {
			j++
		} else {
			break
		}
	}

	if i == len(input2Bytes) {
		return true
	} else {
		return false
	}
}

