func sortAsc(numbers string) (result string) {
	splitResult := strings.Split(numbers, "+")
	if len(splitResult) <= 1 {
		result = numbers
		return
	}

	var index int
	var isSwap bool
	for {
		if splitResult[index] > splitResult[index+1] {
			temp := splitResult[index]
			splitResult[index] = splitResult[index+1]
			splitResult[index+1] = temp
			isSwap = true
		} else {
			isSwap = false
		}

		index++
		if index == len(splitResult)-1 {
			index = 0
			if !isSwap {
				break
			}
		}
	}

	var sb strings.Builder
	for i, number := range splitResult {
		sb.WriteString(number)
		if i < len(splitResult)-1 {
			sb.WriteString("+")
		}
	}

	return sb.String()
}

