type graph struct {
	edges  [][]int
	degree []int
	scc    int
	color  []int
}

func (g *graph) add(from, to int) {
	g.edges[from] = append(g.edges[from], to)
	g.degree[from]++
}

func (g *graph) addBoth(from, to int) {
	g.add(from, to)
	if from != to {
		g.add(to, from)
	}
}

func (g *graph) dfs(v int) {
	g.color[v] = g.scc
	for _, w := range g.edges[v] {
		if g.color[w] == 0 {
			g.dfs(w)
		}
	}
}

func (g *graph) check() bool {
	cnt := 0
	for _, c := range g.color {
		if c == g.scc {
			cnt++
		}
	}
	for i, c := range g.color {
		if c == g.scc && g.degree[i] != cnt-1 {
			return false
		}
	}
	return true
}

