func Sol623A(reader io.Reader, writer io.Writer) {
	in := bufio.NewReader(reader)
	out := bufio.NewWriter(writer)
	defer out.Flush()

	var n, m int
	Fscan(in, &n, &m)
	g := &graph{
		edges:  make([][]int, n+1),
		degree: make([]int, n+1),
		scc:    1,
		color:  make([]int, n+1),
	}
	for ; m > 0; m-- {
		var v, w int
		Fscan(in, &v, &w)
		g.addBoth(v, w)
	}

	g.dfs(1)
	if !g.check() {
		Fprint(out, "No")
		return
	}
	g.scc++
	for i := 2; i <= n; i++ {
		if g.color[i] == 0 {
			g.dfs(i)
			break
		}
	}
	if !g.check() {
		Fprint(out, "No")
		return
	}
	for _, c := range g.color[1:] {
		if c == 0 {
			Fprint(out, "No")
			return
		}
	}

	Fprintln(out, "Yes")
	for _, c := range g.color[1:] {
		if c == 1 {
			Fprint(out, "a")
		} else {
			Fprint(out, "c")
		}
	}
}

