func main() {
	s := bufio.NewScanner(os.Stdin)
	s.Split(bufio.ScanWords)
	s.Scan()
	n, _ := strconv.Atoi(s.Text())
	primes := sieves(n)

	if n == 1 {
		fmt.Println("1")
		return
	} else if n == 2 {
		fmt.Println("2")
		return
	} else if n == 3 {
		fmt.Println("6")
		return
	}

	set := []int64(nil)
	if n%2 == 0 {
		set = append(set, int64(n-1))
	} else {
		set = append(set, int64(n))
	}
	for i := set[0] - 1; i >= 1; i-- {
		isDiv := false
		for j := 0; j < len(set); j++ {
			if i%set[j] == 0 {
				isDiv = true
			}
		}
		if !isDiv {
			set = append(set, i)
		}
		if len(set) == 3 {
			break
		}
	}
	//fmt.Println(set)
	fmt.Println(mul(set, primes))
}

func mul(xs, primes []int64) (ans int64) {
	factors := make([]int64, len(primes))
	for i := 0; i < len(xs); i++ {
		x := xs[i]
		iFactors := make([]int64, len(primes))
		for x > 1 {
			for j := 0; j < len(primes); j++ {
				if x%primes[j] == 0 {
					x /= primes[j]
					iFactors[j]++
					if iFactors[j] > factors[j] {
						factors[j] = iFactors[j]
					}
					break
				}
			}
		}
	}

	ans = 1
	for i := 0; i < len(factors); i++ {
		if factors[i] > 0 {
			ans *= int64(math.Pow(float64(primes[i]), float64(factors[i])))
		}
	}
	return
}

func sieves(n int) (primes []int64) {
	n = n + 1
	xs := make([]bool, n)
	xs[0] = true
	xs[1] = true
	primes = make([]int64, 0, n)
	for i := 2; i < n; i++ {
		for j := i * 2; j < n; j = j + i {
			xs[j] = true
		}
	}

	for i := 0; i < n; i++ {
		if !xs[i] {
			primes = append(primes, int64(i))
		}
	}

	return
}

