func canN(n, a int) bool {
	if n >= a {
		return true
	}
	return false
}

func getStones(a, b, n int) (result int) {
	for n > 0 {
		first := Nod(a, n)
		second := Nod(b, n)
		if canN(n, first) {
			n -= first
			result = 0
		} else {
			result++
			return
		}
		if canN(n, second) {
			n -= second
			result++
		} else {
			result = 0
			return
		}
	}
	return
}

func Nod(a, b int) int {
	var del int
	chastnoe := 0
	del = min(a, b)
	for i := 1; chastnoe != a; i++ {
		if a%i != 0 {
			continue
		}
		del = a / i
		chastnoe = a / del
		if b%del == 0 {
			return del
		}
	}
	return 1
}

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}

