const None = 0
const Red = 1
const Blue = 2
const Green = 4

func colors(r, g, b int) int {
	if r < 0 || g < 0 || b < 0 {
		return None
	}
	// fmt.Println(r, g, b)
	if r == 1 && g == 0 && b == 0 {
		return Red
	}
	if r == 0 && g == 1 && b == 0 {
		return Green
	}
	if r == 0 && g == 0 && b == 1 {
		return Blue
	}

	result := None

	for _, i := range [][]int{
		[]int{r + 1, g - 1, b - 1},
		[]int{r - 1, g + 1, b - 1},
		[]int{r - 1, g - 1, b + 1},
	} {
		result = result | colors(i[0], i[1], i[2])
	}
	if r > 1 {
		result = result | colors(r-1, g, b)
	}
	if g > 1 {
		result = result | colors(r, g-1, b)
	}
	if b > 1 {
		result = result | colors(r, g, b-1)
	}
	return result
}

