		case 'B':
			b++
		}
	}

	// fmt.Println(r, g, b)
	result := colors(r, g, b)
	// fmt.Println(result)
	if (result & Blue) != 0 {
		fmt.Print("B")
	}
	if (result & Green) != 0 {
		fmt.Print("G")
	}
	if (result & Red) != 0 {
		fmt.Print("R")
	}
	fmt.Println()
}

