const MAX = 3

func Sort(A []int, N int) []int {
	q := len(A) / N
	r := len(A) % N
	splits := make([][]int, N)
	pos := 0
	for i := 0; i < N; i++ {
		var delta int
		if i < r {
			delta = q + 1;
		} else {
			delta = q;
		}
		splits[i] = A[pos : pos + delta]
		pos += delta
	}
	waitGroup := new(sync.WaitGroup)
	for i := 0; i < N; i++ {
		waitGroup.Add(1)
		go func(B []int) {
			sort.Ints(B)
			waitGroup.Done()
		}(splits[i])
	}
	waitGroup.Wait()
	B := make([]int, 0);
	next := make([]int, N)
	for len(B) < len(A) {
		idx := -1
		for i := 0; i < N; i++ {
			if next[i] < len(splits[i]) && (idx == -1 || splits[i][next[i]] < splits[idx][next[idx]]) {
				idx = i
			}
		}
		B = append(B, splits[idx][next[idx]])
		next[idx]++
	}
	return B
}

