  left, right := getI64(), getI64()
  total := int64(0)
  max := getNext(right)
  current := left-1
  for {
    next := getNext(current+1)
    if next == max {
      total += (right-current)*next
      break
    }
    total += (next-current)*next
    current = next
  }
  writer.WriteString(fmt.Sprintf("%d\n", total))
}

