type Light struct {
	p complex128
	a float64
}

type Line struct {
	p1, p2 complex128
}

func CrossProduct(a complex128, b complex128) float64 {
	return real(a)*imag(b) - real(b)*imag(a)
}

func Roatate(x complex128, a float64) complex128 {
	r, t := cmplx.Polar(x)
	return cmplx.Rect(r, t+a)
}

func Intersact(a Line, b Line) (intersaction complex128, isIntersact bool) {
	s1 := CrossProduct(a.p2-a.p1, b.p1-a.p1)
	s2 := CrossProduct(a.p2-a.p1, b.p2-a.p1)
	if math.Abs(s2-s1) >= EPS {
		isIntersact = true
		intersaction = complex(real(b.p1)*s2-real(b.p2)*s1, imag(b.p1)*s2-imag(b.p2)*s1) / complex(s2-s1, 0.0)
	}
	return
}

func foo(l float64, lit Light, r float64) float64 {
	v1 := complex(l-real(lit.p), 0-imag(lit.p))
	v2 := Roatate(v1, lit.a)
	if imag(v2) > -EPS {
		return r
	}

	p1 := complex(0.0, 0.0)
	p2 := complex(10.0, 0.0)
	inter, _ := Intersact(Line{lit.p, lit.p + v2}, Line{p1, p2})
	return real(inter)
}

