func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}

func max(a, b int) int {
	if a > b {
		return a
	}
	return b
}

func reverse(s string) (result string) {
	for _, v := range s {
		result = string(v) + result
	}
	return
}

func getMax(m, s int) string {
	r := ""
	for i := 0; i < m; i++ {
		next := min(9, s)
		s -= next
		r += strconv.Itoa(next)
	}
	return r
}

func getMin(m, s int) string {
	h := max(1, s-9*(m-1))
	max := getMax(m-1, s-h)
	return strconv.Itoa(h) + reverse(max)
}

