	for _, value := range a {
		writer.WriteString(strconv.Itoa(value))
	}

	writer.WriteString(" ")

	for _, value := range b {
		writer.WriteString(strconv.Itoa(value))
	}

	writer.Flush()
	os.Exit(0)
}

