	res = k ;

	for i := 2; i <= lim ; i ++ {
		if (k % i) == 0 {
			ot := k / i ; 

			if i > n {
				res = my_min( res , i ) ;
			}

			if ot > n {
				res = my_min( res , ot ) ; 
			}
		} 
