}

func findSquare(a, x, y int) int {
	ha := a
	a *= 2
	x *= 2
	y *= 2

	if -ha < x && x < ha && 0 < y && y < a {
		return 1
	}

	if -ha < x && x < ha && a < y && y < 2*a {
		return 2
	}

	if -a < x && x < 0 && 2*a < y && y < 3*a {
		return 3
	}

	if 0 < x && x < a && 2*a < y && y < 3*a {
		return 4
	}

	if -ha < x && x < ha && 3*a < y && y < 4*a {
		return 5
	}

	if -a < x && x < 0 && 4*a < y && y < 5*a {
		return 6
	}

	if 0 < x && x < a && 4*a < y && y < 5*a {
		return 7
	}

	return -1
}

