	writer := bufio.NewWriterSize(os.Stdout, 1<<13)
	n, a, b, c := ReadInt64(reader), ReadInt64(reader), ReadInt64(reader), ReadInt64(reader)
	ans := min(solve(4-n%4, a, b, c), solve(8-n%4, a, b, c))
	fmt.Fprintln(writer, ans)
	writer.Flush()
}

func solve(n, a, b, c int64) int64 {
	if n < 0 {
		return 1e10
	}
	if n%4 == 0 {
		return 0
	}
	ans := solve(n-1, a, b, c) + a
	ans = min(ans, solve(n-2, a, b, c)+b)
	ans = min(ans, solve(n-3, a, b, c)+c)
	return ans
}

func min(a, b int64) int64 {
	if a < b {
		return a
	}
	return b
}

func ReadInt(reader *bufio.Reader) int {
	return int(ReadInt64(reader))
}

func ReadInt64(reader *bufio.Reader) int64 {
	b, err := reader.ReadByte()
	for !isValid(b, err) {
		b, err = reader.ReadByte()
	}
	var res int64
	for isValid(b, err) {
		res = res*10 + int64(b-'0')
		b, err = reader.ReadByte()
	}
	return res
}

func isValid(b byte, err error) bool {
	return err == nil && '0' <= b && b <= '9'
}

