func main() {
	var n, s int
	fmt.Scan(&n, &s)

	impossible := func() bool {
		switch n {
		case 1:
			if s > 9 {
				return true
			}
		default:
			if s == 0 || s > 9*n {
				return true
			}
		}
		return false
	}

	if impossible() {
		fmt.Println("-1 -1")
		return
	}

	largest := func() string {
		d := make([]int, n)
		x := s
		for i := 0; i < n; i++ {
			d[i] = min(x, 9)
			x -= d[i]
		}
		res := make([]rune, n)
		for i := 0; i < n; i++ {
			res[i] = rune(d[i] + '0')
		}
		return string(res)
	}

	smallest := func() string {
		if n == 1 {
			return fmt.Sprintf("%d", s)
		}
		d := make([]int, n)

		x := s
		k := 0
		if s < 9*(n-1)+1 {
			d[0] = 1
			k = 1
		}
		for i := n - 1; i >= k; i-- {
			d[i] = min(x, 9)
			x -= d[i]
		}
		res := make([]rune, n)
		for i := 0; i < n; i++ {
			res[i] = rune(d[i] + '0')
		}
		return string(res)
	}

	fmt.Println(smallest(), largest())
}

