    qb:=b/p
    k:=t/p/qw/qb
    m:=min(w,b)-1
    r:=k + m*k + min(m,t-k*p*qw*qb)
    rt:=gcd(r,t)
    r,t=r/rt,t/rt
    fmt.Printf("%d/%d\n",r,t)
}

