func isSubsequence(s, t string) bool {
	if len(s) < len(t) {
		return false
	}

	i, j := 0, 0

	for j < len(t) && i < len(s) {
		if s[i] == t[j] {
			i++
			j++
		} else {
			i++
		}
	}

	return j == len(t)
}

