	defer w.Flush()
	var id string
	for I(&id, "\n") == nil {
		if solve(id) {
			O("YES", "\n")
		} else {
			O("NO", "\n")
		}
	}
}
func solve(id string) bool {
	pattern := "^[a-zA-Z0-9_]{2,15}@([a-zA-Z0-9_]{2,15}\\.?)*(\\/[a-zA-Z0-9_]{2,15})?$"
	if regexp.MustCompile(pattern).MatchString(id) {
		o := strings.Split(id, "@")
		if strings.Contains(o[1], "/") {
			o = append([]string{o[0]}, strings.Split(o[1], "/")...)
		}
		if len(o[1]) > 1 && len(o[1]) < 32 && o[1][len(o[1])-1] != '.' {
			return true
		}
	}
	return false
}

