func isalpha(c rune) bool {
	if c >= 'a' && c <= 'z' {
		return true;
	}
	if c >= 'A' && c <= 'Z' {
		return true;
	}
	return false;
}

func isdigit(c rune) bool {
	if c >= '0' && c <= '9' {
		return true;
	}
	return false;
}

func do_str(s string) bool {
	idx := strings.Index(s, "@");
	if idx == -1 {
		// No "@"
		return false;
	}

	username := s[0:idx];
	if len(username) > 16 || len(username) < 1 {
		return false;
	}

	for _, c := range(username) {
		if isalpha(c) { continue }
		if isdigit(c) { continue }
		if c == '_' { continue }
		return false
	}

	if len(s[idx:]) == 1 {
		return false;
	}
	var resource string;
	var hostname string;

	rest := s[idx+1:]
	idx = strings.Index(rest, "/");
	if idx == -1 {
		resource = "";
		hostname = rest;
	} else {
		resource = rest[idx:];
		if len(resource) == 1 {
			return false;
		}
		resource = resource[idx+1:]
		hostname = rest[0:idx];
	}

	if len(hostname) < 1 || len(hostname) > 32 {
		return false
	}
	for _, c := range(hostname) {
		if isalpha(c) { continue }
		if isdigit(c) { continue }
		if c == '_' { continue }
		if c == '.' { continue }
		return false
	}
	words := strings.Split(hostname, ".");
	for _, word := range(words) {
		if len(word) < 1 || len(word) > 16 {
			return false;
		}
	}
	if len(resource) > 16 {
		return false;
	}
	for _, c := range(resource) {
		if isalpha(c) { continue }
		if isdigit(c) { continue }
		if c == '_' { continue }
		return false
	}

	return true
}

