func sort(a, b, c int64) (int64, int64, int64) {
	x := max(c, max(a, b))
	z := min(c, min(a, b))
	y := a + b + c - x - z
	return x, y, z
}

func min(a, b int64) int64 {
	if a < b {
		return a
	} else {
		return b
	}
}

func max(a, b int64) int64 {
	if a > b {
		return a
	} else {
		return b
	}
}

func write(num ...int64) {
	for _, value := range num {
		str := strconv.FormatInt(value, 10) + " "
		out.WriteString(str)
	}
	out.WriteString("\n")
}

func read(num ...*int64) {
	for _, value := range num {
		in.Scan()
		*value, _ = strconv.ParseInt(in.Text(), 10, 64)
	}
