		case g >= r && g >= b:
			g -= 2
			if r > b {
				r--
			} else {
				b--
			}
		case b >= g && b >= r:
			b -= 2
			if g > r {
				g--
			} else {
				r--
			}
		default:
			panic("do not reach here")
		}
		z++
	}
	fmt.Println(z)
}

