func ReadInt32(scanner *bufio.Scanner) int {
  scanner.Scan()
  ans, _ := strconv.Atoi(scanner.Text())
  return ans
}

func ReadString(scanner *bufio.Scanner) string {
  scanner.Scan()
  ans := scanner.Text()
  return ans
}

func PrintInt(writer *bufio.Writer, value int) {
  writer.WriteString(strconv.Itoa(value))
  writer.WriteByte(' ')
}

func PrintInts(writer *bufio.Writer, ints ...int) {
  for _, value := range ints {
    writer.WriteString(strconv.Itoa(value))
    writer.WriteByte(' ')
  }
  writer.WriteByte('\n')
}

func main() {
  var scanner *bufio.Scanner = bufio.NewScanner(os.Stdin)
  var writer *bufio.Writer = bufio.NewWriter(os.Stdout)
  defer writer.Flush()
  scanner.Split(bufio.ScanWords)

  n, k := ReadInt32(scanner), ReadInt32(scanner)
  hn := n / 2
  total := n * (n - 1) / 2

  if k >= hn {
    k = hn
    PrintInt(writer, total)
    return 
  }
  PrintInts(writer, n, k, hn)

  total -= (n - k) * (n - k - 1) / 2
  total += k * (n - 2 * k)
  total += k * (k - 1) / 2

  PrintInt(writer, total)
  writer.WriteByte('\n')
}

