)

var in = bufio.NewScanner(os.Stdin)
var out = bufio.NewWriter(os.Stdout)

type Team struct {
	name string
	pts, x, y, played int
}

type Sorter []Team

func (s Sorter) Len() int { return len(s) }
func (s Sorter) Swap(i, j int) { s[i], s[j] = s[j], s[i] }
func (s Sorter) Less(i, j int) bool { 
	if s[i].pts > s[j].pts {
		return true
	}
	if s[i].pts < s[j].pts {
		return false
	}
	if s[i].x - s[i].y > s[j].x - s[j].y {
		return true
	}
	if s[i].x - s[i].y < s[j].x - s[j].y {
		return false
	}
	if s[i].x > s[j].x {
		return true
	}
	if s[i].x < s[j].x {
		return false
	}
	return s[i].name < s[j].name
}

func main() {
	defer out.Flush()
	in.Split(bufio.ScanWords)

	s2m := make(map[string]*Team)
	for i := 0; i < 5; i++ {
		name1, name2, score := Next(), Next(), Next()
		if _, exists := s2m[name1]; !exists {
			s2m[name1] = &Team{name: name1}
		}

		if _, exists:= s2m[name2]; !exists {
			s2m[name2] = &Team{name: name2}
		}

		t1, _ := s2m[name1]
		t2, _ := s2m[name2]

		s := strings.Split(score, ":")
		s1, _ := strconv.Atoi(s[0])
		s2, _ := strconv.Atoi(s[1])

		t1.played += 1
		t2.played += 1
		t1.x += s1
		t1.y += s2
		t2.x += s2
		t2.y += s1

		if s1 > s2 {
			t1.pts += 3
		}else if s1 < s2 {
			t2.pts += 3
		}else {
			t1.pts += 1
			t2.pts += 1
		}
	}

	var berland, other Team
	var teams [4]*Team
	var at int = 0
	for _, value := range s2m {
		teams[at] = value
		at += 1

		if value.played == 2 {
			if value.name == "BERLAND" {
				berland = *value
			}else {
				other = *value
			}
		}
	}

	berland.pts += 3
	berland.played += 1

	other.played += 1

	// fmt.Fprintln(out, berland)

	var score1, score2 int = -1, -1
	for x := 0; x < 1000; x++ {
		for y := 0; y < x; y++ {
			b := make([]Team, 0)
			for i := 0; i < 4; i++ {
				if teams[i].name == berland.name || teams[i].name == other.name {
					continue
				}
				b = append(b, *teams[i])
			}

			// fmt.Fprintln(out, b)

			brld, othr := berland, other
			brld.x += x
			brld.y += y
			othr.x += y
			othr.y += x
			b = append(b, brld)
			b = append(b, othr)
			sort.Sort(Sorter(b))

			// fmt.Fprintln(out, b)

			if b[0].name == berland.name || b[1].name == berland.name {
				if score1 == -1 || score1 - score2 > x - y || (score1 - score2 == x - y && score2 > y){
					score1, score2 = x, y
				}
			}
		}
	}

	if score1 == -1 {
		fmt.Fprintln(out, "IMPOSSIBLE")
	}else {
		fmt.Fprintln(out, score1, score2)
	}	
}

