	var x, y float64
	sq := Square{}
	for i := 0; i < 4; i++ {
		fmt.Scan(&x, &y)
		sq.Points[i] = Point{
			X: x,
			Y: y,
		}
	}

	sq45 := Square{}
	for i := 0; i < 4; i++ {
		fmt.Scan(&x, &y)
		sq45.Points[i] = Point{
			X: x,
			Y: y,
		}
	}

	if solve(sq, sq45) {
		fmt.Println("YES")
	} else {
		fmt.Println("NO")
	}
}

