// https://codeforces.com/contest/981/problem/A
func problem(c Contest)  {
	s := c.In.Str()
	l := len(s)
	e := true // same chars

	for i := 0; i < len(s) / 2; i++ {
		if i > 0 {
			e = e && (s[i] == s[i-1])
		}

		if s[i] != s[l - i - 1] {
			// Not palindrome
			c.Out.Int(l).N()
			return
		}
	}

	// Palindrome
	if e {
		c.Out.Int(0).N()
	} else {
		c.Out.Int(l - 1).N()
	}
}

