func main() {
	var n int
	fmt.Scan(&n)
	var word string
	fmt.Scan(&word)
	fmt.Println(replace(word))
}

func replace(word string) string {
	ans := ""
	for i := 0; i < len(word); i++ {
		if word[i] == 'o' {
			last := findLast(word, i)
			if last > i {
				ans += "***"
				i = last
			} else {
				ans += string(word[i])
			}
		} else {
			ans += string(word[i])
		}
	}
	return string(ans)
}

func findLast(word string, pos int) int {
	for i := pos; i < len(word); i++ {
		expected := byte('o')
		if (i-pos)&1 == 1 {
			expected = 'g'
		}
		if word[i] != expected {
			if word[i-1] == 'o' {
				return i - 1
			} else {
				return i - 2
			}
		}
	}
	return len(word) - 1
}

