)

const (
	MaxN = 128
)

type exam struct {
	s, d, c, index int
}

var n, m int
var e [MaxN]exam
var s [MaxN]int

func main() {
	fmt.Scanf("%d %d\n", &n, &m)
	for i := 0; i < m; i++ {
		fmt.Scanf("%d %d %d\n", &e[i].s, &e[i].d, &e[i].c)
		e[i].index = i + 1
	}
	sort.Slice(e[:m], func(i, j int) bool {
		return e[i].d < e[j].d
	})
	for i := 0; i < m; i++ {
		s[e[i].d] = m + 1
	}
	for i := 0; i < m; i++ {
		start := e[i].s
		for ;start <= n; start++ {
			if s[start] == 0 {
				break
			}
		}
		if start == n+1 {
			fmt.Println(-1)
			return
		}
		for counter := 0; counter < e[i].c; {
			if s[start + counter] != 0  {
				if start + counter == e[i].d {
					fmt.Println(-1)
					return
				}
				start++
				continue
			}
			s[start + counter] = e[i].index
			counter++
		}
	}
	for i := 1; i <= n; i++ {
		fmt.Printf("%d ", s[i])
	}
}

