import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)
	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	var n int
	var m int

	fmt.Fscan(in, &n, &m)

	s := make([]int, m)
	d := make([]int, m)
	c := make([]int, m)
	sched := make([]int, n)
	for i := 0; i < n; i++ {
		sched[i] = 0
	}

	for i := 0; i < m; i++ {
		fmt.Fscan(in, &s[i], &d[i], &c[i])
		s[i]--
		d[i]--
		sched[d[i]] = m + 1
	}

	fail := false

	for i := 0; i < n; i++ {
		bestt := n + 10
		bestj := -1
		for j := 0; j < m; j++ {
			if s[j] <= i && i < d[j] && c[j] > 0 {
				t := 0

				for k := i; k < d[j]; k++ {
					if sched[k] == 0 {
						t++
					}
				}

				t -= c[j]

				if t < bestt {
					bestt = t
					bestj = j
				}
			}
		}

		if bestt < 0 {
			fail = true
			break
		}

		if bestj != -1 {
			sched[i] = bestj + 1
			c[bestj]--
		}
	}

	for i := 0; i < m; i++ {
		if c[i] > 0 {
			fail = true
			break
		}
	}

	if !fail {
		for i := 0; i < n; i++ {
			fmt.Fprint(out, sched[i], " ")
		}

		fmt.Fprintln(out)
	} else {
		fmt.Fprintln(out, -1)
	}

}

