func main() {
	var n, a, b, c int
	fmt.Scan(&n, &a, &b, &c)
	//maxP := bruteForce(n, a, b, c)
	maxP := dp(n, a, b, c)
	fmt.Print(maxP)
}

func dp(n, a, b, c int) int {
	dp := make([]int, n+1)
	dp[a] = 1
	dp[b] = 1
	dp[c] = 1
	for i := 1; i <= n; i++ {
		dp[i] = max(dp, i, i-a, i-b, i-c)
	}
	return dp[n]
}

func max(dp []int, nrs ...int) int {
	m := dp[nrs[0]]
	for _, nr := range nrs[1:] {
		if nr < 0 || dp[nr] == 0 {
			continue
		}
		if dp[nr]+1 > m {
			m = dp[nr] + 1
		}
	}
	return m
}

func bruteForce(n, a, b, c int) int {
	var maxP int
	ls := []int{a, b, c}
	sort.Sort(sort.Reverse(sort.IntSlice(ls)))
	for i := 0; i <= n/ls[0]; i++ {
		for j := 0; j <= n/ls[1]; j++ {
			d := n - i*ls[0] - j*ls[1]
			if d%ls[2] == 0 {
				k := d / ls[2]
				if maxP < i+j+k {
					maxP = i + j + k
				}
			}
		}
	}
	return maxP
}

