import (
	"math"
	"fmt"
)

const maxN = 4000

func intMax(a, b int) int {
	if a < b {
		return b
	}

	return a
}

func resolver(a, b, c, n int) int {
	if n > maxN {
		panic("Limit exceeded")
	}

	memo := make([]int, n+1)
	units := make([]int, 3)

	units[0], units[1], units[2] = a, b, c
	memo[0] = 0
	memo[a] = 1
	memo[b] = 1
	memo[c] = 1

	for i := 1; i <= n; i++ {
		var localMax int = math.MinInt32

		for _, v := range(units) {
			if delta := i - v; delta >= 0 {
				var localMaxCand int = intMax(localMax, memo[delta] + 1)

				if localMaxCand > localMax {
					localMax = localMaxCand
					memo[i] = localMax
				}
			}
		}

		memo[i] = localMax
	}

	return memo[n]
}

func main() {
	var n, a, b, c int
	fmt.Scanln(&n, &a, &b, &c)

	fmt.Println(resolver(a, b, c, n))
}

