func Readln(r *bufio.Reader) (string, error) {
	var (
		isPrefix bool  = true
		err      error = nil
		line, ln []byte
	)
	for isPrefix && err == nil {
		line, isPrefix, err = r.ReadLine()
		ln = append(ln, line...)
	}
	return string(ln), err
}

func readIntArray(line string) []int {

	numStrings := strings.Split(strings.TrimSpace(string(line)), " ")

	numbers := make([]int, 0)

	for _, v := range numStrings {
		var converted int

		fmt.Sscanf(v, "%d", &converted)
		numbers = append(numbers, converted)
	}

	return numbers
}

func main() {
	reader := bufio.NewReader(os.Stdin)

	line, _ := Readln(reader)
	numbers := readIntArray(line)

	length := numbers[0]
	lengths := numbers[1:]

	cache := make(map[int]int, 0)
	fmt.Println(Cut(length, lengths, 0, cache))
}

func Cut(length int, lengths []int, pieces int, cache map[int]int) int {

	if cached, ok := cache[length]; ok {
		return cached
	}

	maxPieces := pieces
	isCut := false
	for _, ln := range lengths {
		if (length - ln) >= 0 {
			newPieces := Cut(length - ln, lengths, pieces + 1, cache)
			if maxPieces < newPieces {
				isCut = true
				maxPieces = newPieces
			}
		}
	}

	if (!isCut) && length > 0 {
		maxPieces = -1
		cache[length] = maxPieces
	} else if isCut && length == 0 {
		cache[length] = maxPieces
	}

	return maxPieces
}

