import "fmt"

func sortThree(a, b, c int) (int, int, int) {
	if a > b {
		a, b = b, a
	}
	if b > c {
		b, c = c, b
	}
	if a > b {
		a, b = b, a
	}
	return a, b, c
}

// https://codeforces.com/problemset/problem/189/A
// комментарии к решению
// Задача решается перебором. Для сокращения кол-ва комбинаций
// пытаемся сначала разрезать ленту на максимальное кол-во мелких кусочков,
// уменьшая их кол-во с каждой итерацией пробуем разрезать оставшуюся часть
// на ленты среднего размера, проводя аналогичный критерий выбора для
// среднего/крупного размера.
func taskSolution(n, a, b, c int) int {
	a, b, c = sortThree(a, b, c)
	max := 0
	for i := n / a; i >= 0; i -= 1 {
		for j := (n - i*a) / b; j >= 0; j -= 1 {
			for k := (n - i*a - j*b) / c; k >= 0; k -= 1 {
				if n == i*a+j*b+k*c && max < i+j+k {
					max = i + j + k
				}
			}
		}
	}
	return max
}

func main() {
	var n, a, b, c int
	if _, err := fmt.Scan(&n, &a, &b, &c); err != nil {
		panic(err)
	}

	fmt.Println(taskSolution(n, a, b, c))
}

