func main() {
	sc := NewScanner()
	N, K := sc.NextInt(), sc.NextInt()
	a := sc.NextIntArray()

	double := N * 2
	forth := make([][]int, N)
	for i := 0; i < N; i++ {
		forth[i] = make([]int, 2)
	}
	forth_pointer := 0
	for i := 0; i < K; i++ {
		q := a[i] / 4
		for k := 0; k < q; k++ {
			if forth_pointer < 2*N {
				forth[forth_pointer/2][forth_pointer%2] = i + 1
				forth_pointer++

				forth[forth_pointer/2][forth_pointer%2] = i + 1
				forth_pointer++
				a[i] -= 4
			}
		}
	}
	for i := 0; i < K; i++ {

		q := a[i] / 2

		diff := min(double, q)
		a[i] -= diff * 2
		double -= diff
	}
	for num := 2; num >= 1; num-- {

		for i := 0; i < K; i++ {
			q := a[i] / num
			e := forth_pointer
			for k := 0; k < q; k++ {
				if double > 0 {
					double--
					a[i] -= num
					continue
				}
				for ; e < 2*N; e++ {
					if num == 2 && e%2 == 1 {
						o := e - 1
						if forth[o/2][0] == i+1 {
							forth_pointer += 2
						} else {
							continue
						}
					}
					forth[e/2][e%2] = i + 1
					a[i] -= num
					e++
					break
				}
			}
		}
	}

	for i := 0; i < K; i++ {
		if a[i] > 0 {
			fmt.Println("NO")
			return
		}
	}
