// IsPrime judges whether an argument integer is a prime number or not.
func IsPrime(n int) bool {
	var i int

	if n == 1 {
		return false
	}

	for i = 2; i*i <= n; i++ {
		if n%i == 0 {
			return false
		}
	}

	return true
}

