func mark_rock(board *[9][9]int, pos_r pos){
    for i:=pos_r.x+1; i<=8; i++{
        if board[i][pos_r.y] < 2 {
            board[i][pos_r.y] = 1
        }else{
            break
        }
    }
    for i:=pos_r.x-1; i>=1; i--{
        if board[i][pos_r.y] < 2 {
            board[i][pos_r.y] = 1
        }else{
            break
        }
    }
    for j:=pos_r.y+1; j<=8; j++{
        if board[pos_r.x][j] < 2 {
            board[pos_r.x][j] = 1
        }else{
            break
        }
    }
    for j:=pos_r.y-1; j>=1; j--{
        if board[pos_r.x][j] < 2 {
            board[pos_r.x][j] = 1
        }else{
            break
        }
    }
}

func is_valid(x int, y int) bool{
    if x>=1 && x<=8{
        return y>=1 && y<=8
    }
    return false
}

