    for i:=0; i<3; i++{
        for j:=0; j<3; j++{
            x:= pos_k.x+move_x[i]
            y:= pos_k.y+move_y[j]
            if !is_valid(x,y){
                continue
            }
            if board[x][y] >=2{
                continue
            }
            board[x][y] = 1
        }
    }
}

