            if x==0 && y==0{
                continue
            }
            if !is_valid(x,y){
                continue
            }
            if board[x][y] == 2{
                return "OTHER"
            }
            if board[x][y] == 0{
                return "OTHER"
            }
        }
    }
    return "CHECKMATE"
}

