var cnt []int64

func recv(n, k int64) byte {
	if n == 0 {
		if k < int64(len(f0)) {
			return f0[k]
		}
		return '.'
	}
	if k < int64(len(a)) {
		return a[k]
	}
	k -= int64(len(a))

	if k < cnt[n-1] {
		return recv(n-1, k)
	}
	k -= int64(cnt[n-1])

	if k < int64(len(b)) {
		return b[k]
	}

	k -= int64(len(b))

	if k < cnt[n-1] {
		return recv(n-1, k)
	}
	k -= int64(cnt[n-1])

	if k < int64(len(c)) {
		return c[k]
	}
	return '.'

}

