type Solution struct {
	Moves    int
	Category string
}

func Solve(x int) Solution {
	category := map[int]string{
		1: "A",
		3: "B",
		2: "C",
		0: "D",
	}
	moves := 0
	bestMoves := 0
	bestCategory := category[x%4]
	for x+moves <= 100 {
		currentCategory := category[(x+moves)%4]
		if currentCategory < bestCategory {
			bestMoves = moves
			bestCategory = currentCategory
		}
		moves += 1
	}
	return Solution{Moves: bestMoves, Category: bestCategory}
}

func main() {
	reader := bufio.NewReader(os.Stdin)
	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	var x int
	fmt.Fscanf(reader, "%d\n", &x)

	solution := Solve(x)
	fmt.Fprintf(writer, "%d %s\n", solution.Moves, solution.Category)
}

