func verifyReallyBig(num int, minDiff int) (isReallyBig bool, diff int) {
	sum := 0
	for n := num; n > 0; n /= 10 {
		sum += n % 10
	}
	diff = num - sum
	if diff >= minDiff {
		isReallyBig = true
	} else {
		isReallyBig = false
	}
	return
}

func searchMin(n int, s int) (min int) {
	var left, right, diff int
	var isReallyBig bool
	for left, right, diff = 1, n/10 + 1, math.MaxInt32; right > left; {
		min = (left + (right - left) / 2) * 10
		isReallyBig, diff = verifyReallyBig(min, s)
		if isReallyBig {
			right = min / 10
		} else {
			left = min / 10 + 1
		}
	}
	if (diff < s) {
		min = n + 1
	}
	return min
}

func Solve(input io.Reader) (result string) {
	var n, s int
	fmt.Fscan(input, &n, &s)
	return fmt.Sprintln(n - searchMin(n, s) + 1)
}

func main() {
	fmt.Print(Solve(os.Stdin))
}

