import (
	"fmt"
	"sort"
)

func main() {
	var n, x int
	fmt.Scan(&n)

	if n == 1 {
		print(0)
		return
	}

	cntOdd := (n + 1) / 2
	cntEven := n / 2
	var odd, even []int
	last, emptyLen := -1, 0
	ans := 0
	for i := 0; i < n; i++ {
		fmt.Scan(&x)

		if x == 0 {
			emptyLen++
			continue
		}

		x %= 2
		if x == 1 {
			cntOdd--
		} else {
			cntEven--
		}

		if last != -1 && x != last {
			ans++
		}

		if emptyLen > 0 {
			if last == -1 || last == x {
				// begin or same parity
				if x == 0 {
					even = append(even, emptyLen)
				} else {
					odd = append(odd, emptyLen)
				}
			}
			emptyLen = 0
		}
		last = x
	}

	if last == -1 {
		print(1)
		return
	}
	if emptyLen > 0 {
		if last == 0 {
			even = append(even, emptyLen)
		} else {
			odd = append(odd, emptyLen)
		}
	}
	// fmt.Println("ans", ans, "cntOdd", cntOdd, "cntEven", cntEven)
	// fmt.Println("even", even)
	// fmt.Println("odd", odd)
	sort.Ints(even)
	sort.Ints(odd)
	ans += len(even) + len(odd)
	for _, x = range even {
		if x > cntEven {
			break
		}
		cntEven -= x
		ans--
	}
	for _, x = range odd {
		if x > cntOdd {
			break
		}
		cntOdd -= x
		ans--
	}
	print(ans)
}

