	var n, k, d int
	for I(&n, &k, &d) == nil {
		solve(n, k, d)
	}
}

func solve(n, k, d int) {
	if d > n {
		O("0\n")
		return
	}
	O(do(n, k, d)-1, "\n")
}

func do(n, k, d int) int {
	if n < 0 {
		return 0
	}
	ans := 1
	for i := d; i <= k; i++ {
		ans += do(n-i, k, 1)
		ans %= 1e9 + 7
	}
	return ans
}

