func scanf(f string, a ...interface{}) { fmt.Fscanf(reader, f, a...) }

const MOD = 1000000007
var n, k, d int

func solve (sum, ok int, dp [][]int) int {
	if sum > n {
		return 0
	}
	if sum == n {
		return ok
	}

	if dp[ok][sum] != -1 {
		return dp[ok][sum]
	}

	ways := 0
	for weight := 1; weight <= k; weight++ {
		if weight >= d {
			ways = (ways + solve(sum+weight, 1, dp)) % MOD
		} else {
			ways = (ways + solve(sum+weight, ok, dp)) % MOD
		}
	}

	return ways
}

func main() {
	scanf("%d %d %d\n", &n, &k, &d)

	if n < d {
		fmt.Println(0)
	}
	dp := make([][]int, 2)
	dp[0] = make([]int, 102)
	dp[1] = make([]int, 102)

	for i := 0; i < 102; i++ {
		dp[0][i] = -1
		dp[1][i] = -1
	}

	solve(0,0, dp)
	fmt.Println(solve(0, 0, dp))
}

