import "fmt"

func minSlots(n int64) int {
	c := 1
	s := int64(7)
	for {
		if s > n {
			return c
		}
		c ++;
		s *= 7
	}
}

var n, m int64
var slotN, slotM int
var ans = 0
var used = make([]bool, 7)
func cal(num []int) int64 {
	var result int64
	for _, n := range num {
		result = result * int64(7) + int64(n)
	}
	return result
}
func dfs(num []int) {
	if len(num) == slotN {
		if cal(num[:slotN]) >= n {
			return
		}
	} else if len(num) == slotN + slotM {
		if cal(num[slotN:]) < m {
			ans ++
		}
		return
	}
	for i, use := range used {
		if !use {
			used[i] = true
			dfs(append(num, i))
			used[i] = false
		}
	}
}

func main() {
	fmt.Scanf("%d %d", &n, &m)
	slotN = minSlots(n)
	slotM = minSlots(m)
	num := make([]int, 0, slotN + slotM + 1)
	dfs(num)
	fmt.Println(ans)
}

