func validate(arr []int64, nSlots int, n int64, m int64) bool {
  length := len(arr)
  for i:= 0; i < length; i++ {
    for j:= i+1; j < length; j++ {
      if arr[i] == arr[j] {
        return false
      }
    }
  }
  var num int64
  for i:=0; i < nSlots; i++ {
    num = num*7+arr[i]
  }
  if num >= n {
    return false
  }
  num = 0
  for i:=nSlots; i < length; i++ {
    num = num*7+arr[i]
  }
  if num >= m {
    return false
  }
  //fmt.Println(arr)
  return true
}

