package main

import (
	"bufio"
	"fmt"
	"os"
)

type Position struct {
	X int
	Y int
}

type Node struct {
	Maria Position
	Time  int
}

func getNeighbors(p Position) []Position {
	neighbors := []Position{
		{X: p.X - 1, Y: p.Y - 1},
		{X: p.X - 1, Y: p.Y},
		{X: p.X - 1, Y: p.Y + 1},
		{X: p.X, Y: p.Y - 1},
		{X: p.X, Y: p.Y},
		{X: p.X, Y: p.Y + 1},
		{X: p.X + 1, Y: p.Y - 1},
		{X: p.X + 1, Y: p.Y},
		{X: p.X + 1, Y: p.Y + 1},
	}
	var validNeighbors []Position
	for _, neighbor := range neighbors {
		if 0 <= neighbor.X && neighbor.X < 8 && 0 <= neighbor.Y && neighbor.Y < 8 {
			validNeighbors = append(validNeighbors, neighbor)
		}
	}
	return validNeighbors
}

func hasStatue(board [8]string, p Position, time int) bool {
	if 0 <= p.X-time && p.X-time < 8 {
		if string(board[p.X-time][p.Y]) == "S" {
			return true
		}
	}
	if 0 <= p.X-time-1 && p.X-time-1 < 8 {
		if string(board[p.X-time-1][p.Y]) == "S" {
			return true
		}
	}
	return false
}

func Solve(board [8]string) string {
	stack := []Node{{Maria: Position{X: 7, Y: 0}, Time: 0}}
	for {
		currentNode, stack := stack[len(stack)-1], stack[:len(stack)-1]
		if currentNode.Time == 8 || currentNode.Maria.X == 0 {
			return "WIN"
		}
		for _, neighbor := range getNeighbors(currentNode.Maria) {
			if !hasStatue(board, neighbor, currentNode.Time) {
				stack = append(stack, Node{Maria: neighbor, Time: currentNode.Time + 1})
			}
		}
		if len(stack) == 0 {
			break
		}
	}
	return "LOSE"
}

func main() {
	reader := bufio.NewReader(os.Stdin)
	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	var board [8]string
	for i := 0; i < 8; i++ {
		fmt.Fscanf(reader, "%s\n", &board[i])
	}
	fmt.Fprintf(writer, "%s\n", Solve(board))
}

