	total := 0
	for i := 0; i < len(ans)-1; i++ {
		a, _ := strconv.Atoi(ans[i])
		total += a
		if findGolden(total, ans[i+1:]) {
			fmt.Print("YES")
			return
		}
	}
	fmt.Print("NO")
}

func findGolden(cut int, rem []string) bool {
	total := 0
	for i := 0; i < len(rem); i++ {
		a, _ := strconv.Atoi(rem[i])

		total += a
		if total > cut {
			return false
		}
		if total == cut {
			return i+1 == len(rem) || findGolden(cut, rem[i+1:])

		}
	}
	return false
}

