func do() {
	s := bufio.NewScanner(os.Stdin)
	s.Split(bufio.ScanWords)
	s.Scan()
	n, _ := strconv.Atoi(s.Text())
	s.Scan()
	m, _ := strconv.Atoi(s.Text())
	s.Scan()
	k, _ := strconv.ParseInt(s.Text(), 10, 64)
	s.Scan()
	x, _ := strconv.Atoi(s.Text())
	s.Scan()
	y, _ := strconv.Atoi(s.Text())

	min := minAsk(n, m, k)
	max := maxAsk(n, m, k)
	cnt := count(n, m, x, y, k)
	fmt.Printf("%v %v %v\n", max, min, cnt)
}

func minAsk(n, m int, k int64) int64 {
	if n <= 2 {
		return k / int64(n*m)
	}

	t := int64(2*n*m - 2*m)
	th := int64(n * m)
	d := k / t
	r := k % t

	if r < th {
		return d
	}
	return d + 1
}

func maxAsk(n, m int, k int64) int64 {
	if n <= 2 {
		d := k / int64(n*m)
		r := k % int64(n*m)
		if r > 0 {
			return d + 1
		}
		return d
	}

	t := int64(2*n*m - 2*m)
	th := int64(n * m)
	d := k / t
	r := k % t

	if r <= int64(m) {
		return d * 2
	} else if r <= th {
		return d*2 + 1
	}

	return d*2 + 2
}

func count(n, m, x, y int, k int64) int64 {
	if n <= 2 {
		d := k / int64(n*m)
		r := k % int64(n*m)
		if r >= int64((x-1)*m+y) {
			return d + 1
		}
		return d
	}

	t := int64(2*n*m - 2*m)
	th := int64(n * m)
	d := k / t
	r := k % t

	if x == 1 {
		if r >= int64(y) {
			return d + 1
		}
		return d
	} else if x == n {
		if r-int64((n-1)*m) >= int64(y) {
			return d + 1
		}
		return d
	} else {
		if r < int64((x-1)*m+y) {
			return d * 2
		} else if r >= int64((x-1)*m+y) && r < th+int64((n-x-1)*m+y) {
			return d*2 + 1
		}
	}

	return d*2 + 2
}

