func GetAt(N, M, R, C, K int64) int64 {
	R--
	C--
	var cnt int64
	if N == 1 {
		cnt = K / M
		if C < K % M {
			cnt++
		}
	} else {
		T := M * (N + N - 2)
		P := K / T
		if R == 0 || R == N - 1 {
			cnt = P
		} else {
			cnt = P * 2
		}
		rem := K % T
		// fmt.Printf("(%d, %d), T = %d, P = %d, cnt = %d, rem = %d\n", R, C, T, P, cnt, rem)
		// fmt.Printf("  idx1 = %d, idx2 = %d\n", (M * R) + C, M * ((2 * N) - R - 2) + C)
		if R < N - 1 && (M * R) + C < rem {
			cnt++
		}
		if M * ((2 * N) - R - 2) + C < rem {
			cnt++
		}
	}
	// fmt.Printf("  cnt = %d\n", cnt)
	return cnt
}

