const mod = 998244353

var factor [200005]int64

func getFactorial(n int) {
	factor[0], factor[1] = 1, 1
	var i int64
	for i = 2; i <= int64(n); i++ {
		factor[i] = factor[i-1] * i % mod
	}
}

func quickPow(base int64, p int) int64 {
	var answer int64 = 1
	for p > 0 {
		if p & 1 == 1 {
			answer = answer * base % mod
		}
		base = base * base % mod
		p >>= 1
	}
	return answer
}

func inv(n int64) int64 {
	return quickPow(n, mod - 2)
}

func comb(n, m int) int64 {
	return factor[n] * inv(factor[n-m]*factor[m]%mod) % mod
}

func main() {
	var n, k int
	_, _ = fmt.Scan(&n)
	_, _ = fmt.Scan(&k)
	if n < k {
		fmt.Println(0)
	} else if k == 1 {
		fmt.Println(n)
	} else if k == n {
		fmt.Println(1)
	} else {
		var factor = 1
		var answer int64 = 0
		getFactorial(n)
		for n/factor >= k {
			answer = (answer + comb(n/factor-1, k-1)) % mod
			factor++
		}
		fmt.Println(answer)
	}
}

