const MAX_N = 100010
const MOD = 998244353

var F []int64
var IF []int64

// var PM []int

func pow(a, b int64) int64 {
	var r int64 = 1
	for b > 0 {
		if b&1 == 1 {
			r *= a
			r %= MOD
		}
		a *= a
		a %= MOD
		b >>= 1
	}
	return r
}

func init() {
	// PM = make([]int, 0, 10000)
	// PM = append(PM, 1)
	// set := make([]bool, MAX_N)

	// for x := 2; x < MAX_N; x++ {
