func main() {
	reader := bufio.NewReader(os.Stdin)
	line1, _ := reader.ReadString('\n')
	line1_arr := strings.Fields(line1)
	// fmt.Println(line1_arr)
	T, _ := strconv.Atoi(line1_arr[0])
	//fmt.Println("T:", T)
	for t := 0; t < T; t++ {
		line2, _ := reader.ReadString('\n')
		line2_arr := strings.Fields(line2)
		N, _ := strconv.Atoi(line2_arr[0])
		K, _ := strconv.Atoi(line2_arr[1])
		L, _ := strconv.Atoi(line2_arr[2])
		// fmt.Println(N, K, L)
		line3, _ := reader.ReadString('\n')
		Astr := strings.Fields(line3)
		A := make([]int, N)
		var safe []int
		soln_possible := true
		for i:=0; i<N; i++ {
			A[i], _ = strconv.Atoi(Astr[i])
			if A[i] + K <= L {
				safe = append(safe, i)
			} else if A[i] > L {
				fmt.Println("No")
				soln_possible = false
				break
			}
		}
		//fmt.Println("A:", A)
		//fmt.Println("safe:", safe)

		if !soln_possible {
			continue
		}

		safe_ind := 0
		lower_bound := -1
		upper_bound := N
		if len(safe) > 0 {
			upper_bound = safe[safe_ind]
		}
		res := "Yes"
		for true {			

			retval := is_path_safe(lower_bound, upper_bound, K, L, A)
			//	fmt.Println("is_path_safe() beg: ", lower_bound, "end: ", upper_bound, "retval: ", retval)
			if !retval {
				res = "No"
				break
			} else {
				if safe_ind > len(safe) -1 {
					break 
				}

				lower_bound = safe[safe_ind]
				safe_ind++
				if safe_ind > len(safe) -1 {
					upper_bound = N
				} else {
					upper_bound = safe[safe_ind]
				}
			}
		}

		fmt.Println(res)
	}
}

func is_path_safe(beg, end, K, L int, A []int) bool {	
	abeg := beg + 1
	aend := end - 1
	if abeg >= aend {
		return true
	}

	t := 0
	k := K
	for i:=abeg; i<=aend; i++ {
		x := A[i] + k - L
		if x > 0 {
			t += x
			k = get_k_phase(K, k, t)
		} else {
			t++
		}


	}

	// fmt.Println("t: ", t)
	if t >= 2*K {
		return false
	}

	return true
}

func get_k_phase(K, k, t int) int {
	t %= 2*K
	if t <= K {
		return k - t
	} else {
		return k
	}
}

