func solveD(l, n, k int64) (int64) {

	gc := gcd(l, n*k)
	tmp := n * k/gc
	if tmp < 0{
		fmt.Printf("%d %d %d\n",l,n,k)
	}
	tmp *= l
	if tmp < 0{
		fmt.Printf("-%d %d %d\n",l,n,k)
	}
	return tmp / l
}
