func Solve(board [8]string) string {
	highestWhitePawn := 0
	lowestBlackPawn := 0
	for j := 0; j < 8; j++ {
		for i := 0; i < 8; i++ {
			if string(board[i][j]) == "B" {
				break
			} else if string(board[i][j]) == "W" {
				highestWhitePawn = i
				break
			}
		}
		for i := 7; i >= 0; i-- {
			if string(board[i][j]) == "W" {
				break
			} else if string(board[i][j]) == "B" {
				lowestBlackPawn = i
				break
			}
		}
	}
	if highestWhitePawn <= 7-lowestBlackPawn {
		return "A"
	}
	return "B"
}

func main() {
	reader := bufio.NewReader(os.Stdin)
	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	var board [8]string
	for i := 0; i < 8; i++ {
		fmt.Fscanf(reader, "%s\n", &board[i])
	}
	fmt.Fprintf(writer, "%s\n", Solve(board))
}

