func solve(cards [5]int) int {
	sort.Ints(cards[:])
	if cards[3] == cards[4] {
		if cards[2] == cards[3] {
			return cards[0] + cards[1]
		}
		return cards[0] + cards[1] + cards[2]
	}
	// cards[3] != cards[4]
	if cards[2] == cards[3] {
		if cards[1] == cards[2] {
			return cards[0] + cards[4]
		}
		return cards[0] + cards[1] + cards[4]
	}
	// cards[2] != cards[3]
	if cards[1] == cards[2] {
		if cards[0] == cards[1] {
			return cards[3] + cards[4]
		}
		return cards[0] + cards[3] + cards[4]
	}
	// cards[1] != cards[2]
	if cards[0] == cards[1] {
		return cards[2] + cards[3] + cards[4]
	}
	// cards[0] != cards[1]
	return cards[0] + cards[1] + cards[2] + cards[3] + cards[4]
}

