func gcd(a, b int) int {
  sign := 1
  if a < 0 {
    a = -a
    sign = -sign
  }
  if b < 0 {
    b = -b
    sign = -sign
  }
  for b != 0 {
    a, b = b, a%b
  }
  return sign*a
}

