func minKol(sum uint32) uint32 {
	bills := [...]uint32{1, 5, 10, 20, 100}
	var uint32 mode = sum
	var uint32 rez
	var int i = 4

	for mode != 0 {
		rez = rez + mode/bills[i]
		mode = sum % bills[i]
		mode = mode % bills[i]
		i--
	}
	return rez
}

