const ZERO int = int('0')

func process(s string) []int {
    var cnt [10]int
    for _, c := range s {
        cnt[int(c) - ZERO]++
    }
    return cnt[:]
}

func getMax(cnt []int) string {
    var buffer bytes.Buffer
    for i := 9; i >= 0; i-- {
        for j := 0; j < cnt[i]; j++ {
            buffer.WriteRune(rune(i + ZERO))
        }
    }
    return buffer.String()
}

func main() {
    var a, b string
    fmt.Scan(&a, &b)
    cnt := process(a)
    var ans string
    if len(b) > len(a) {
        ans = getMax(cnt)
    } else {
        var buffer bytes.Buffer
        valid := true
        for i, c := range b {
            numb := int(c) - ZERO

            // attempt to go lower
            for numb--; cnt[numb] == 0 && numb >= 0; numb-- {}
            if numb >= 0 {
                buffer.WriteRune(rune(numb + ZERO))
                cnt[numb]--
                buffer.WriteString(getMax(cnt))
                ans = buffer.String()
                cnt[numb]++
                buffer.Truncate(i)
            }

            // reset
            numb = int(c) - ZERO
            if cnt[numb] > 0 {
                buffer.WriteRune(c)
                cnt[numb]--
            } else {
                for ; cnt[numb] == 0 && numb >= 0; numb-- { }
                if numb >= 0 {
                    buffer.WriteRune(rune(numb + ZERO))
                    cnt[numb]--
                    buffer.WriteString(getMax(cnt))
                } else {
                    valid = false
                }
                break
            }
        }
        if valid {
            ans = buffer.String()
        }
    }
    fmt.Println(ans)
}

