func solve() {
	a := []byte(strconv.FormatInt(readInt64(), 10))
	b := []byte(strconv.FormatInt(readInt64(), 10))
	anum := make([]int, len(a))
	for i := 0; i < len(a); i++ {
		anum[i] = int(a[i] - '0')
	}
	bnum := make([]int, len(b))
	for i := 0; i < len(b); i++ {
		bnum[i] = int(b[i] - '0')
	}
	sort.Sort(sort.Reverse(sort.IntSlice(anum)))
	if len(a) == len(b) {
		dfs(anum, bnum, 0)
	}
	for _, v := range anum {
		fmt.Print(v)
	}
	fmt.Println()
}

func dfs(anum []int, bnum []int, pos int) bool {
	if pos == len(anum) {
		return true
	}
	for i := pos; i < len(anum); i++ {
		if anum[i] < bnum[pos] {
			anum[pos], anum[i] = anum[i], anum[pos]
			resort(anum, pos+1)
			return true
		}
		if anum[i] <= bnum[pos] {
			anum[pos], anum[i] = anum[i], anum[pos]
			resort(anum, pos+1)
			if dfs(anum, bnum, pos+1) {
				return true
			}
			resort(anum, pos)
		}
	}
	return false
}

func resort(nums []int, pos int) {
	for i := pos; i < len(nums)-1; i++ {
		for j := i + 1; j < len(nums); j++ {
			if nums[i] < nums[j] {
				nums[i], nums[j] = nums[j], nums[i]
			}
		}
	}
}

