func permute(a []int, n int, b int64, ans int64) {
	if n == 0 {
		zeroes := 0
		for i := 0; i < len(a); i++ {
			if a[i] == 0 {
				zeroes++
			} else {
				break
			}
		}

		rs := make([]rune, len(a)-zeroes)
		for i := 0; i < len(a)-zeroes; i++ {
			rs[i] = rune(a[i+zeroes]) + '0'
		}
		fmt.Println(string(rs))
		return
	}

	i := len(a) - n
	d := a[i]
	for ans+int64(d)*powInt(10, n-1) > b {
		i++
		d = a[i]
	}
	swap(a, len(a)-n, i)
	sort.Sort(sort.Reverse(sort.IntSlice(a[len(a)-n+1:])))
	permute(a, n-1, b, ans+int64(d)*powInt(10, n-1))
}

