	reader  = bufio.NewReader(os.Stdin)
	writer  = bufio.NewWriter(os.Stdout)
)

func main() {
	defer writer.Flush()
	scanner.Split(bufio.ScanWords)
	n := nextInt()
	res := 0
	nFact := factorial(n)
	for i := 1; i <= n; i++ {
		down := factorial(i) * factorial(n-i)
		res += nFact / down
	}
	println(res)

}
func factorial(x int) int {
	if x == 0 {
		return 1
	}

	return x * factorial(x-1)
}

func scan(a ...interface{}) {
	fmt.Fscan(reader, a...)
}

func next() string {
	if !scanner.Scan() {
		panic("Scan error")
	}
	return scanner.Text()
}

func nextInt() int {
	n, _ := strconv.Atoi(next())
	return n
}

func println(a ...interface{}) {
	fmt.Fprintln(writer, a...)
}

