func checkInputs() int {
	in := getInput()
	index, _ := strconv.Atoi(strings.Split(in[0], " ")[1])
	count := 0

	values := strings.Split(in[1], " ")

	check, _ := strconv.Atoi(values[index])

	for _, val := range values {
		v, err := strconv.Atoi(val)
		if err != nil {
			log.Fatal(err)
		}

		if v > 0 && v >= check {
			count++
			continue
		}
	}
	return count
}

func getInput() []string {
	inputs := []string{}
	reader := bufio.NewReader(os.Stdin)

	for len(inputs) != 2 {
		s, err := reader.ReadString('\n')
		if err != nil && err != io.EOF {
			log.Fatal(err)
		}
		s = strings.TrimRight(s, "\r\n")
		inputs = append(inputs, s)
	}
	return inputs
}

