func main() {
	var n int
	var k int
	var scores []int
	var scanner = bufio.NewScanner(os.Stdin)
	n, k = takeInput(scanner)
	scores = getScores(scanner)

	fmt.Println(checkScores(n, k, scores))

}

func takeInput(scanner *bufio.Scanner) (int, int) {

	scanner.Scan()
	tempInput := strings.Split(scanner.Text(), " ")
	var n int
	n, _ = strconv.Atoi(tempInput[0])
	var k int
	k, _ = strconv.Atoi(tempInput[1])
	return n, k
}

func getScores(scanner *bufio.Scanner) []int {
	var input string
	var scores []int

	scanner.Scan()
	input = scanner.Text()

	tempScores := strings.Split(input, " ")

	for _, scoreString := range tempScores {
		score, _ := strconv.Atoi(scoreString)
		scores = append(scores, score)
	}

	return scores
}

func checkScores(n int, k int, scores []int) int {

	var advancers int = 0
	for _, value := range scores {
		if value <= 0 {
			return advancers
		}
		if value >= scores[k] {
			advancers++
		}
	}
	return advancers
}

