func Round(_r io.Reader, _w io.Writer) {
	in := bufio.NewReader(_r)
	out := bufio.NewWriter(_w)
	defer out.Flush()

	var T, target, si int
	var result []int
	Fscan(in, &T)
	Fscan(in, &target)

	for ; T > 0; T-- {
		Fscan(in, &si)
		result = append(result, si)
	}

	var mid int
	i, j := 0, len(result)-1
	for i <= j {
		mid = (i + j) / 2
		if result[mid] < result[target] {
			j = mid - 1
		} else if result[mid] > result[target] {
			i = mid + 1
		} else {
			if result[target] == 0 {
				for ; mid > 0; mid-- {
					if result[mid] != result[target] {
						break
					}
				}

				Fprintln(out, mid)

			} else {

				for ; mid < len(result); mid++ {
					if result[mid] != result[target] {
						break
					}
				}

				Fprintln(out, mid)
			}

			return
		}
	}

	Fprintln(out, mid+1)

}

