func (sq *Sq) isPara() bool {
	chk1, chk2 := false, false

	for i := 2; i < 8; i = i + 2 {
		if sq.v[i] == sq.v[0] {
			chk1 = true
		}
	}
	for i := 3; i < 8; i = i + 2 {
