func check2in1(s1 *Sq, s2 *Sq, j int) bool {
	xin, yin := false, false

	xlarge, xsmall := 0, 0
	ylarge, ysmall := 0, 0
	for i := 0; i < 8; i = i + 2 {
		if s1.v[i] < s2.v[j*2] {
			xlarge = xlarge + 1
		}
		if s1.v[i] > s2.v[j*2] {
			xsmall = xsmall + 1
		}
	}
	if xlarge != 4 && xsmall != 4 {
		xin = true
	}

	for i := 1; i < 8; i = i + 2 {
		if s1.v[i] < s2.v[j*2+1] {
			ylarge = ylarge + 1
		}
		if s1.v[i] > s2.v[j*2+1] {
			ysmall = ysmall + 1
		}
	}
	if ylarge != 4 && ysmall != 4 {
		yin = true
	}
	if xin && yin {
		return true
	}
	return false
}

func check1in2(s1 *Sq, s2 *Sq, i int) bool {
	xaddy := s1.v[i*2] + s1.v[i*2+1]
	xsuby := s1.v[i*2] - s1.v[i*2+1]

	var xaddy2 [4]int
	var xsuby2 [4]int

	for j := 0; j < 4; j++ {
		xaddy2[j] = s2.v[j*2] + s2.v[j*2+1]
		xsuby2[j] = s2.v[j*2] - s2.v[j*2+1]
	}

  xin, yin := false, false
	xlarge, xsmall := 0, 0
	ylarge, ysmall := 0, 0

	for j := 0; j < 4; j++ {
		if xaddy2[j] < xaddy {
			xlarge = xlarge + 1
		}
		if xaddy2[j] > xaddy {
			xsmall = xsmall + 1
		}
	}
	if xlarge != 4 && xsmall != 4 {
		xin = true
	}

	for j := 0; j < 4; j++ {
		if xsuby2[j] < xsuby {
			ylarge = ylarge + 1
		}
		if xsuby2[j] > xsuby {
			ysmall = ysmall + 1
		}
	}
	if ylarge != 4 && ysmall != 4 {
		yin = true
	}
	if xin && yin {
		return true
	}
	return false

}

