	for i := 0;i < n;i ++ {
		var x, y int
		if i == n - 1 {
			fmt.Fscanf(reader, "%d %d\n", &x, &y)
		} else {
			fmt.Fscanf(reader, "%d %d ", &x, &y)
		}
