	}
	for i := 0;i < m;i ++ {
		var x, y int
		if i == m - 1 {
			fmt.Fscanf(reader, "%d %d\n", &x, &y)
		} else {
			fmt.Fscanf(reader, "%d %d ", &x, &y)
		}
		pb[x][y] = true
		pb[y][x] = true
	}

	solution := make([]bool, 10)

	canDeduce := true
	for i := 1; i < 10;i ++ {
		for j := 1;j < 10;j ++ {
			if !pa[i][j] {
				continue
			}
			var b1, b2 bool
			for k := 1; k < 10;k ++ {
				if pb[i][k] && k != j {
					solution[i] = true
					b1 = true
				}
				if pb[k][j] && k != i {
					solution[j] = true
					b2 = true
				}
			}
			if b1 && b2 {
				canDeduce = false
			}
		}
	}

	ans, ansCount := 0, 0
	for i := 1;i < len(solution);i ++ {
		if solution[i] {
			ans, ansCount = i, ansCount + 1
		}
	}
	if ansCount == 1 {
		fmt.Printf("%d", ans)
	} else if canDeduce {
		fmt.Printf("0")
	} else {
		fmt.Printf("-1")
	}

}

