func fill(matrix [][]int, i int, j int) {
	if matrix[i][j] == 0 && matrix[i][j-1] != 0 && matrix[i-1][j] != 0 {
		matrix[i][j] = matrix[i-1][j] + matrix[i][j-1]
		if i < len(matrix) && j+1 < len(matrix[i]) {
			fill(matrix, i, j+1)
		}
		if i+1 < len(matrix) && j < len(matrix[i]) {
			fill(matrix, i+1, j)
		}
	}
}

