func isRA(A, B, C Pont) bool {
	AB := Pont{B.x - A.x, B.y - A.y}
	AC := Pont{C.x - A.x, C.y - A.y}
	return 0 == AB.x*AC.x+AB.y*AC.y
}

func isRATRI(A, B, C Pont) bool {
	if A.eq(B) || A.eq(C) || B.eq(C) {
		return false
	}
	return isRA(A, B, C) || isRA(B, A, C) || isRA(C, A, B)
}

func main() {

	var (
		P     [3]Pont
		dir   = [4]Pont{Pont{0, 1}, Pont{1, -1}, Pont{-1, -1}, Pont{-1, 1}}
		delta = Pont{1, 0}
		i, j  int32
	)

	P[0].read()
	P[1].read()
	P[2].read()
	if isRATRI(P[0], P[1], P[2]) {
		fmt.Println("RIGHT")
		return
	}

	almost := false

outer:
	for i = 0; i < 3; i++ {
		for j = 0; j < 4; j++ {
			P[i].add(dir[j])
			if isRATRI(P[0], P[1], P[2]) {
				almost = true
				break outer
			}
			P[i].add(delta)
		}
	}

	if almost {
		fmt.Println("ALMOST")

	} else {
		fmt.Println("NEITHER")
	}

}

