const N = 10

type Deck struct {
	cards []int
}

func (d *Deck) addCard(c int) {
	d.cards = append(d.cards, c)
}

func (d *Deck) isLosing() bool {
	return len(d.cards) == 0
}

func (d *Deck) hash() int64 {
	var h int64
	for _, c := range d.cards {
		h = N*h + int64(c)
	}
	return h
}

func oneRound(d1, d2 *Deck) {
	var c1, c2 int
	c1, d1.cards = d1.cards[0], d1.cards[1:]
	c2, d2.cards = d2.cards[0], d2.cards[1:]
	d := d1
	if c1 < c2 {
		c1, c2 = c2, c1
		d = d2
	}
	d.addCard(c2)
	d.addCard(c1)
}

func makeKey(d1, d2 Deck) string {
	return strconv.FormatInt(d1.hash(), 10) + "#" + strconv.FormatInt(d2.hash(), 10)
}

func main() {
	nextInt()
	var d1, d2 Deck
	k1 := nextInt()
	for i := 0; i < k1; i++ {
		d1.addCard(nextInt() - 1)
	}
	k2 := nextInt()
	for i := 0; i < k2; i++ {
		d2.addCard(nextInt() - 1)
	}
	was := make(map[string]struct{})
	for rounds := 0; ; rounds++ {
		if d1.isLosing() {
			fmt.Println(rounds, 2)
			return
		}
		if d2.isLosing() {
			fmt.Println(rounds, 1)
			return
		}
		key := makeKey(d1, d2)
		if _, ok := was[key]; ok {
			break
		}
		was[key] = struct{}{}
		oneRound(&d1, &d2)
	}
	fmt.Println(-1)
}

