func main() {
	var n, m int64
	fmt.Scanf("%d %d", &n, &m)
	cnt := initCount(n)
	dp[0][0] = 1
	var mask int = int(uint(1)<<uint(cnt))
	for i := 1; i < mask; i++ {
		for j, mm := 0, 1; j < cnt; j, mm = j+1, mm<<uint(1) {
			if (i&mm) == 0 {
				continue
			}
			if i == mm && numbers[j] == 0 {
				continue
			}
			for k := int64(0); k < m; k++ {
				dp[i][(k*int64(10) + int64(numbers[j]))%m] += dp[i^mm][k]
			}
		}
	}

	//fmt.Println(dp[mask-1][0])

	for i := 0; i <= 9; i++ {
		for j := 2; j <= count[i]; j++ {
			dp[mask-1][0] /= j
		}
	}

	fmt.Println(dp[mask-1][0])
}

