const maxn = 18
const maxm = 110

var a [1 << maxn][maxm]int64
var s [maxn]int
var cnt [10]int
var wid uint

func allzero(x int) bool {
    for i := uint(0); i < wid; i++ {
        if ((1<<i)&x) != 0 && s[i] != 0 {
            return false
        }
    }
    return true
}

func cc(x int) int {
    ans := 1
    for x != 0 {
        ans *= x
        x--
    }
    return ans
}

func main() {
    scanner.Split(bufio.ScanWords)
    n := scanner.NextInt64()
    m := scanner.NextInt()
    for i := 0; i < 10; i++ {
        cnt[i] = 0
    }
    for i := 0; i < (1 << maxn); i++ {
        for j := 0; j < maxm; j++ {
            a[i][j] = 0
        }
    }
    wid = 0
    for n != 0 {
        s[wid] = int(n % 10)
        cnt[s[wid]]++
        wid++
        n /= 10
    }
    a[0][0] = 1
    for i := 0; i < (1 << wid); i++ {
        if i > 0 && allzero(i) {
            for j := 0; j < m; j++ {
                a[i][j] = 0
            }
        }
        for j := 0; j < m; j++ {
            if a[i][j] == 0 {
                continue
            }
            for k := uint(0); k < wid; k++ {
                if (i & (1 << k)) != 0 {
                    continue
                }
                a[i|(1<<k)][(j*10+s[k])%m] += a[i][j]
            }
        }
    }
    ans := a[(1<<wid)-1][0]
    for i := 0; i < 10; i++ {
        ans = ans / int64(cc(cnt[i]))
    }
    fmt.Println(ans)
}

