func seive_of_eratosthenes(n int64) ([]int64, []bool) {
	var isPrime []bool = []bool{}
	var i int64
	var j int64
	for i = 0; i <= n; i++ {
		isPrime = append(isPrime, true)
	}

	for i = 2; i*i <= (n); i++ {
		if isPrime[i] == true {
			for j = i * i; j <= n; j += i {
				isPrime[j] = false
			}
		}
	}
	var result []int64 = []int64{}
	for i = 2; i <= n; i++ {
		if isPrime[i] == true {
			result = append(result, i)
		}
	}
	return result, isPrime
}

