	// var i int64
	for i := 0; i < len(res)-1; i++ {
		if res[i]+res[i+1]+1 <= n {
			if isPrime[res[i]+res[i+1]+1] == true {
				count++
			}
		}
	}
	if k <= count {
		fmt.Printf("YES\n", count)

	} else {
		fmt.Printf("NO\n")
	}

}

