func main() {
	debug.SetGCPercent(-1)

	fmt.Scanf("%d", &n)
	// n = 14

	calcPrimes(n)

	x1Range := getRange(n)

	x0Range := getRange(x1Range.left)

	for i := x1Range.left + 1; i < x1Range.right; i++ {
		x0Range = joinRanges(x0Range, getRange(i))
	}

	fmt.Println(x0Range.left)
