func min(a, b int) int {
	if a < b {
		return a
	}

	return b
}

func max(a, b int) int {
	if a > b {
		return a
	}

	return b
}

func joinRanges(r1, r2 Range) Range {
	left := min(r1.left, r2.left)

	right := max(r1.right, r2.right)

	return Range{left, right}
}

func getRange(n int) Range {
	divider := findMaxPrimeDivider(n)

	return Range{n - divider + 1, n}
}

func findMaxPrimeDivider(x int) int {
	sqrtx := int(math.Sqrt(float64(x))) + 1

	for i := 0; i < len(primes) && primes[i] < sqrtx; i++ {
		if x%primes[i] == 0 {
			d := x / primes[i]

