func solve(a []int) int {
	m := map[int]bool{}
	var nums []int

	for _, n := range a {
		m[n] = true
	}

	L := len(m)

	if L > 3 {
		return -1
	}

	if L == 1 {
		return 0
	}

	i, avg := 0, 0
	for n := range m {
		nums = append(nums, n)
		avg += n
		i++
	}

	sort.IntSlice(nums).Sort()

	if avg%L > 0 {
		if L == 2 {
			return (nums[1] - nums[0])
		}
		return -1
	}

	avg /= L
	if L == 3 {
		if avg == nums[1] {
			return nums[2] - nums[1]
		}
	}

	if L == 2 {
		if avg%2 == 0 {
			avg /= 2
		}
		return avg
	}

	return -1
}

func toInt(buf []byte) int {
	n, mul := int(0), int(1)
	for i, v := range buf {
		if i == 0 && v == '-' {
			mul = int(-1)
			continue
		}
		n = n*10 + int(v-'0')
	}

	return mul * n
}

