func getUniqueElements(n int, a []int) []int {
	nums := make(map[int]bool)
	elems := []int{}
	for _, elem := range a {
		if !nums[elem] {
			nums[elem] = true
			elems = append(elems, elem)
		}
	}
	return elems
}

func max(x int, y int) int {
	if x > y {
		return x
	}
	return y
}

func Solve(n int, a []int) int {
	b := getUniqueElements(n, a)
	k := len(b)
	if k > 3 {
		return -1
	}
	sort.Ints(b)
	if len(b) == 1 {
		return 0
	}
	diff := b[len(b)-1] - b[0]
	if len(b) == 2 {
		if diff%2 == 1 {
			return diff
		}
		return diff / 2
	}
	if b[1]+diff/2 != b[2] {
		return -1
	}
	return diff / 2
}

