	for b != 0 {
		t := b
		b = a % b
		a = t
	}
	return a
}

func lcm(a, b int64) int64 {
	result := a * b / gcd(a, b)

	return result
}

func main() {
	defer writer.Flush() // STDOUT MUST BE FLUSHED MANUALLY!!!
	var a, b int64
	scan(&a, &b)

	if b < a {
		a, b = b, a
	}

	if b%a == 0 {
		print(0)
		print("\n")
		return
	}

	d := b - a
	sqrtD := math.Sqrt(float64(d))
	var divs []int64
	for i := int64(1); i <= int64(sqrtD); i++ {
		if d%i == 0 {
			nxt := d / i
			divs = append(divs, i)
			if nxt != i {
				divs = append(divs, nxt)
			}
		}
	}

	lcmMin := math.Inf(1)
	minK := math.Inf(1)

	for _, q := range divs {
		if a%q != b%q {
			continue
		}
		var val float64
		k := q
		if a%q == 0 {
			val = float64(lcm(int64(a+q), int64(b+q)))
		} else {
			k = q - (a % q)
			val = float64(lcm(int64(a+k), int64(b+k)))
		}
		if val < lcmMin {
			lcmMin = val
			minK = float64(k)
		}
	}

	print(int(minK))
	print("\n")
}

