func transform(s string) string {
	t := strings.Split(s, "e")

	a := t[0][:1]
	d := t[0][2:]

	b, _ := strconv.Atoi(t[1])
	for len(d) < b {
		d = d + "0"
	}

	r := a + d[:b]
	if b < len(d) {
		r = r + "." + d[b:]
	}

	return r
}

