func Trim(x string, begin, end bool) string {
    var a, b int = 0, len(x) - 1

    if begin {
        for string(x[a]) == "0" && a < b && string(x[a + 1]) != "."{
            a++
        }
    }

    if end {
        for (string(x[b]) == "0" || string(x[b]) == ".") && b > a {
            b--
        }
    }

    return x[a:b + 1]
}

type ExponentialNumber struct {
    n string
    exp string
}

func (e ExponentialNumber) String() string {
    var result string
    var s string = e.n
    var length int = len(s)
    exp, _ := strconv.Atoi(e.exp)
    exp += 1

    var buffer bytes.Buffer

    var fs int = exp
    if fs > length {
        fs = length

        buffer.WriteString(s)

        for i := 0; i < exp - length; i++ {
            buffer.WriteString("0")
        }

        result = Trim(buffer.String(), true, false)
    } else {
        buffer.WriteString(Trim(s[:fs], true, false))

        var p string = Trim(s[fs:], false, true)
        if p != "0" {
            buffer.WriteString(".")
            buffer.WriteString(p)
        }

        result = buffer.String()
    }

    return result
}

func main() {
    var input string
    fmt.Scanln(&input)
    var a_s string //= fmt.Sprint(a), fmt.Sprint(d)

    var buffer bytes.Buffer

    i := 0
    for i < len(input) {
        if string(input[i]) == "e" {
            break
        }

        if string(input[i]) != "." {
            buffer.WriteByte(input[i])
        }

        i++
    }

    a_s = buffer.String()

    e := ExponentialNumber{a_s, input[i + 1:]}

    fmt.Println(e)
}

