func power(x float64, y int) float64 {
	var temp float64
	if y == 0 {
		return 1
	}
	temp = power(x, y/2)
	if y%2 == 0 {
		return temp * temp
	} else {
		if y > 0 {
			return x * temp * temp
		}
		return (temp * temp) / x
	}
}

