import "fmt"

func main() {
	var input string
	var stateArray = 0
	var resetArray = func() {
		stateArray = 0
	}
	var countArray = func() int {
		return (stateArray&8)>>3 + (stateArray&4)>>2 + (stateArray&2)>>1 + (stateArray & 1)
	}

	fmt.Scanln(&input)

	for _, v := range input {
		var c = uint(0)

		switch v {
		case '.':
			c = 0
			break
		case 'A':
			c = 1
			break
		case 'B':
			c = 2
			break
		case 'C':
			c = 3
			break
		default:
			panic("should not reach here")
		}

		if c == 0 {
			resetArray()
			continue
		}

		if ((1 << c) & stateArray) > 1 {
			resetArray()

			stateArray = 1 << c
		} else {
			stateArray |= 1 << c
		}

		if countArray() == 3 {
			fmt.Println("YES")
			return
		}
	}

	fmt.Println("NO")
}

