func main() {
	//log.SetOutput(os.Stdout)
	log.SetOutput(ioutil.Discard)

	io := NewStdIO()
	defer io.Flush()
	d := diameter{io: io}

	l1 := d.io.NextSplitLine(" ")
	n, dmax := stoi(l1[0]), stoi(l1[1])
	log.Printf("n=%d, dmax=%d", n, dmax)

	if n <= 1 {
		d.out(0)
