	}

	l2 := d.io.NextSplitLine(" ")
	nset := make([]int, n)
	for i, ns := range l2 {
		nset[i] = stoi(ns)
	}
	sort.Ints(nset)

	minN := 101
	for i := 0; i < n; i++ {
		cnt := 0
		for j := i; j < n; j++ {
			log.Printf("i=%d, j=%d, minN=%d", i, j, minN)
			if (nset[j] - nset[i]) > dmax {
				minN = min(minN, n-cnt)
				break
			}
			cnt++
		}
	}
	if minN == 101 {
