	"os"
)

func main() {
	scanner := bufio.NewScanner(os.Stdin)

	n, m, k := 0, 0, 0
	if scanner.Scan() {
		line := scanner.Text()

		fmt.Sscanf(line, "%d %d %d", &n, &m, &k)

		bestSize := -1
		for i := 0; i < n && i < k+1; i++ {
			var size_n, size_m, size_n1, size_n2, size_m1, size_m2 int

			size_n1 = n / (i + 1)
			size_n2 = n - size_n1*(i)

			if size_n1 > size_n2 && size_n2 != 0 {
				size_n = size_n2
			} else {
				size_n = size_n1
			}

			if m < k-i+1 {
				continue
			}
			size_m1 = m / (k - i + 1)
			size_m2 = m - size_m1*(k-i)
			if size_m1 > size_m2 && size_m2 != 0 {
				size_m = size_m2
			} else {
				size_m = size_m1
			}

			if size_n*size_m > bestSize {
				bestSize = size_n * size_m
			}
		}
		fmt.Println(bestSize)
	}
}

