func main() {
	var n int
	if _, err := fmt.Scanf("%d\n", &n); err != nil {
		return
	}

	min := make([]int, 3)
	max := make([]int, 3)

	for i := 0; i < 3; i++ {
		if _, err := fmt.Scanf("%d %d\n", &min[i], &max[i]); err != nil {
			return
		}
		if max[i] > n {
			max[i] = n
		}
	}

	var f, s, t int
	var ok bool = false

	for i := max[0]; i >= min[0]; i-- {
		ami := n - i - max[2]
		if ami < min[1] {
			ami = min[1]
		}
		amx := n - i - min[2]
		if amx > max[1] {
			amx = max[1]
		}
		for j := ami; j >= amx; j-- {
			k := n - i - j
			if k >= min[2] && k <= max[2] {
				f = i
				s = j
				t = k
				ok = true
				break
			}
		}
		if ok {
			break
		}
	}

	fmt.Printf("%d %d %d\n", f, s, t)
}

