import "fmt"

func main() {
	var n int
	var freq [10]int
	_, _ = fmt.Scanf("%d\n", &n)
	for i :=0; i < n; i++ {
		for j := 0; j < 6; j++ {
			var num int
			if j < 5 {
				_, _ = fmt.Scanf("%d", &num);
			} else {
				_, _ = fmt.Scanf("%d\n", &num);
			}
			freq[num]++
		}
	}
	for i := 1; i <= 999; i++ {
		temp := i
		var taken [3]int;
		var till = 0
		for temp > 0 {
			digit := temp % 10
			if freq[digit] > 0 {
				freq[digit]--;
				taken[till] = digit
			} else {
				fmt.Println(i - 1)
				return
			}
			till++
			temp /= 10
		}
		for j := 0; j < till; j++ {
			freq[taken[j]]++
		}
	}
	fmt.Println(999)
}

