import "fmt"

func Process(a []int64) (int64, []int64) {
	var m = map[int64]bool{}
	var r = make([]int64, 0)

	for i := len(a) - 1; i >= 0; i-- {
		if _, exist := m[a[i]]; !exist {
			r = append([]int64{a[i]}, r...)
		}

		m[a[i]] = true
	}

	return int64(len(r)), r
}

func main() {
	var n int64

	fmt.Scanln(&n)

	var a, _ = ScanN(n)

	var r1, r2 = Process(a)

	fmt.Println(r1)
	PrintSlice(r2)
}

func ScanN(n int64) ([]int64, error) {
	in := make([]int64, n)
	for i := range in {
		_, err := fmt.Scan(&in[i])
		if err != nil {
			return in[:i], err
		}
	}
	return in, nil
}

func PrintSlice(a []int64) {
	for i := 0; i < len(a); i++ {
		if i == len(a)-1 {
			fmt.Print(a[i])
		} else {
			fmt.Print(a, " ")
		}
	}
}

