func Solve(io *FastIO) {
	N := io.NextInt()
	A := io.NextIntArray(N)

	seen := make(map[int]bool)
	good := make([]bool, N)
	for i := N - 1; i >= 0; i-- {
		if !seen[A[i]] {
			seen[A[i]] = true
			good[i] = true
		}
	}

	for i, v := range A {
		if good[i] {
			io.Printf("%d ", v)
		}
	}
	io.Println()
}

