func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Split(bufio.ScanWords)
	scanner.Scan()
	n, _ := strconv.Atoi(scanner.Text())
	g, cur := [][]int{[]int{-1}}, 0

	for i := 0; i < n; i++ {
		scanner.Scan()
		num, _ := strconv.Atoi(scanner.Text())
		if g[cur][len(g[cur])-1] == num-1 {
			g[cur] = append(g[cur], num)
		} else {
			g = append(g, []int{num})
			cur++
		}
	}

	sum := 0
	for _, v := range g {
		if len(v) < 2 {
			continue
		}
		if (v[0] == 1) || (v[len(v)-1] == 1000) {
			sum += len(v) - 1
		} else {
			sum += len(v) - 2
		}
	}
	fmt.Println(sum)
}

