func solution(x int64) int64 {
	var temp int64
	temp = 1
	var count int64
	count = 0
	for temp < x/2 {
		temp = temp * 2
		count++
	}
	if temp*2 == x {
		return 0
	}
	if temp%2 == 1 {
		count++
	}
	return count
}

