func findMinBacteries(n float64) int {
	c := 0
	for p := 0; n > 0; p++ {
		s := math.Pow(2, float64(p))
		if s > n {
			n -= math.Pow(2, float64(p-1))
			p = 0
			c++
		} else if s == n {
			n = 0
			c++
		}
	}
	return c
}

