func solve() {
    n := readInt()
    init := [2]int{}
    a, c := make([][2]int, n), make([]int, n)
    for i := 0; i < n; i++ {
        ch := readString()
        if ch == "B" {
            c[i] = 1
        }
        for j := range a[i] {
            v := readInt()
            if v > n {
                init[j] += v-n
                v = n
            }
            a[i][j] = v
        }
    }

    const inf = 100000000
    const mx = 1<<16
    mem := [mx][2][16*16+1]int{}
    was := [mx]bool{}
    for i, v := range mem {
        for col, u := range v {
            for j := range u {
                mem[i][col][j] = inf
            }
        }
    }
    mem[0][0][0] = 0

    ans := inf
    d := [mx][2]int{}
    q := []int{0}
    was[0] = true
    for len(q) > 0 {
        cur := q[0]
        curD := d[cur]
        //fmt.Println("BFS", cur, curD)
        for col, u := range mem[cur] {
            for cnt, val := range u {
                if cur == (1<<uint(n))-1 {
                    ans = min(ans, val)
                }

                r, b := 0, 0
                if col == 0 {
                    r = cnt
                } else {
                    b = cnt
                }

                for bit := 0; bit < n; bit++ {
                    mask := 1 << uint(bit)
                    if cur & mask == 0 {
                        next := cur | mask
                        priceR, priceB := max(a[bit][0]-curD[0], 0), max(a[bit][1]-curD[1], 0)
                        //fmt.Println(" Price", priceR, priceB, val)
                        steps := max(priceR-r, priceB-b)
                        nextR, nextB := r+steps-priceR, b+steps-priceB
                        nextCol, nextVal := 0, nextR+nextB
                        if nextB > 0 {
                            nextCol = 1
                        }
                        if nextVal < len(u) {
                            mem[next][nextCol][nextVal] = min(mem[next][nextCol][nextVal], val+steps+1)
                            //fmt.Println(" Updated", next, nextCol, nextVal, "->", mem[next][nextCol][nextVal])
                        }

                        if !was[next] {
                            was[next] = true

                            nextD := curD
                            nextD[c[bit]]++
                            d[next] = nextD

                            q = append(q, next)
                        }
                    }
                }
            }
        }
        q = q[1:]
    }

    ans += max(init[0], init[1])
    fmt.Println(ans)
}



