func genPrimes() []int {
	primes := make([]int, 0, 170)
	var isDivisible [1001]bool
	for i := 2; i <= 1000; i++ {
		if !isDivisible[i] {
			primes = append(primes, i)
			for j := i + i; j <= 1000; j += i {
				isDivisible[j] = true
			}
		}
	}
	return primes
}

func max(a, b int) int {
	if a > b {
		return a
	}
	return b
}

func main() {
	N := nextInt()
	if N == 1 {
		fmt.Println("1 0")
		return
	}
	primes := genPrimes()

	primeFactors := make(map[int]int)
	for _, p := range primes {
		for N%p == 0 {
			N /= p
			primeFactors[p]++
		}
		if N == 1 {
			break
		}
	}

	if N != 1 {
		primeFactors[N]++
	}

	maxExp := 0
	for _, exp := range primeFactors {
		if exp > maxExp {
			maxExp = exp
		}
	}

	pow := 1
	numSqrts := 0
	muls := 0

	bitlen := bits.Len(uint(maxExp))
	if bitlen < maxExp {
		bitlen++
	}
	numSqrts = bitlen - 1
	pow = 1 << uint(bitlen-1)

	var base int64 = 1
	for p, exp := range primeFactors {
		base *= int64(p)
		if exp < pow {
			muls = 1
		}
	}

	fmt.Println(base, muls+numSqrts)
}

