		//fmt.Printf("before:%d ,after:%d\n",res,ret)
		if ret == res {
			break
		} else {
			step++
			res=ret
		}
	}
	if res==n {//prime
		step=0
	}else if res*res!=n {//square
		step=step+1
	}
	fmt.Println(res,step)
}

