func findMaxProffit(berriesCost int, days []int) int {
	maxDiff := 0
	for i := 0; i < len(days)-1; i++ {
		left := days[i]
		right := days[i+1]
		currentDiff := left - right
		if currentDiff > maxDiff {
			maxDiff = currentDiff
		}
	}
	return maxDiff - berriesCost
}

