func solve(j Jam) {
	size := int32(j.Int())
	infinite := false
	sum := int32(0)
	prevPrevFigure := int64(0)
	prevFigure := int64(0)
	for i := int32(0); i < size; i++ {
		figure := j.Int();
		switch figure {
		case 1: //	circle
			switch prevFigure {
			case 1:
				infinite = true
			case 2:
				sum += 3
			case 3:
				sum += 4
			}
		case 2: //	triangle
			switch prevFigure {
			case 1:
				if prevPrevFigure == 3 {
					sum += 2
				} else {
					sum += 3
				}
			case 2:
				infinite = true
			case 3:
				sum += 3
			}
		case 3: //	square
			switch prevFigure {
			case 1:
				sum += 4
			case 2:
				infinite = true
			case 3:
				infinite = true
			}
		}
		if infinite {
			break
		}

		prevPrevFigure = prevFigure
		prevFigure = figure
	}
	if infinite {
		j.P("Infinite\n")
	} else {
		j.P("Finite\n")
		j.P("%d\n", sum)
	}
}

