func Recur(n int, parts []int, count int) (int, error) {
    var result int
    var err error
    if n == 0 {
        result = count
    } else {
        if n < 0 {
            err = errors.New("Error")
        } else {
            for _, part := range parts {
                answ, check := Recur(n - part, parts, count + 1)
                if check == nil && answ > result {
                    result = answ
                }
            }
        }

    }

    return result, err
}

