func power(n, mod int64) int64 {
	if n == 0 {
		return int64(1)
	}
	if n % 2 == 0 {
		x := power(n/2, mod)
		return (x*x) % mod
	} else {
		x := power(n/2, mod)
		return (2*x*x) % mod
	}
}

