	scanner.Scan()
	mod := int64(1000)
	mod = mod*mod*mod + 7
	n, _ := strconv.ParseInt(scanner.Text(), 10, 64)
	a := power(n-1, mod)
	b := (2*a+1) % mod
	x := (a * b) % mod
	writer.WriteString(fmt.Sprintf("%d\n", x))
}

