)

const maxP int64 = 140

var (
	nProd  [maxP]*big.Int
	fact   [maxP]*big.Int
	bigNcr [maxP]*big.Int
	ncr    [maxP]int64
)

func main() {
	var n, p, q int64
	var md *big.Int = big.NewInt(int64((int64(1) << 32) - 1))
	var imd int64 = int64((int64(1) << 32) - 1)
	fmt.Scanf("%d%d%d", &n, &p, &q)
	fmt.Println(n, p, q)
	for i := int64(0); i < maxP; i++ {
		bigNcr[i] = big.NewInt(1)
		fact[i] = big.NewInt(1)
		nProd[i] = big.NewInt(1)
	}
	for i := int64(1); i < maxP; i++ {
		nProd[i].Mul(nProd[i-1], big.NewInt(int64(n-i+1)))
		fact[i].Mul(fact[i-1], big.NewInt(int64(i)))
	}
	for i := int64(0); i < maxP; i++ {
		bigNcr[i].Div(nProd[i], fact[i])
		bigNcr[i].And(bigNcr[i], md)
		ncr[i] = bigNcr[i].Int64()
	}
	var x, m int64
	x = 0
	if p < (n - 1) {
		m = p
	} else {
		m = n - 1
	}
	for i := int64(1); i <= q; i++ {
		var s, pw int64
		s = 0
		pw = 1
		for j := int64(0); j <= m; j++ {
			s += ncr[j] * pw
			s &= imd
			pw = (pw * i) & imd
		}
		x ^= (i * s) & imd
	}
	fmt.Println(x)
}

