func Converster(a byte) int {
	switch {
	case int(a) < 58:
		return int(a) - 48
	case int(a) == 84: //T
		return 10
	case int(a) == 74: //J
		return 11
	case int(a) == 81: //Q
		return 12
	case int(a) == 75: //K
		return 13
	case int(a) == 65: //A
		return 14
	}
	return 0
}

func Check(table string, hand []string) bool {
	for _, val := range hand {
		if table[1] == val[1] {
			if Converster(val[0]) > Converster(table[0]) {
				return true
			}
		}
	}
	if Converster(table[0]) == 14 {
		for _, val := range hand {
			if Converster(val[0]) == 14 {
				return true
			}
		}
	}
	return false
}

