	"fmt"
	"os"
)

const mod =  998244353
var n, m, L, R int

func pw(a int, b int) int {
	if a == 0 {
		if b == 0 {
			return 1
		}
		return 0
	}
	var ret = 1
	for b > 0 {
		if (b & 1) == 1 {
			ret = int(int64(ret) * int64(a) % mod)
			b--
		} else {
			a = int(int64(a) * int64(a) % mod)
			b /= 2
		}
	}
	return ret
}

func main()  {
	var reader = bufio.NewReader(os.Stdin)
	var writer = bufio.NewWriter(os.Stdout)
	defer writer.Flush()
	fmt.Fscanf(reader, "%d %d %d %d", &n, &m, &L, &R)

	var diff = R - L + 1
	var odd = diff / 2
	var evn = diff / 2

	if diff % 2 != 0 {
		if L % 2 == 0 {
			evn++
		} else {
			odd++
		}
	}

	var T = int(int64(n) * int64(m) % (mod - 1))
	var ret = pw(evn + odd, T)
	ret = (ret + pw(evn - odd, T)) % mod

	if ret < 0 {
		ret += mod
	}

	ret = int(int64(ret) * int64(pw(2, mod - 2)) % mod)
	fmt.Fprintf(writer, "%d", ret)
}

