var bestTimes int
var m int
var ret []int

func main() {
	reader := bufio.NewReader(os.Stdin)
	var n int
	fmt.Fscanln(reader, &n, &m)
	max := 0
	if n > m {
		bestTimes = n - m
		max = n
	} else {
		bestTimes, max = initBestTimes(n, m)
	}
	ret = make([]int, max*2+1)
	for i := 0; i < len(ret); i++ {
		ret[i] = -1
	}
	dfs1(n, 0)
	fmt.Println(bestTimes)
}

func dfs1(n int, count int) {
	if count > bestTimes {
		return
	}
	if n == m {
		if count < bestTimes {
			bestTimes = count
		}
		return
	}
	if n == 0 {
		return
	}
	if n-1 < len(ret) && ret[n-1] == -1 {
		dfs1(n-1, count+1)
	}
	if n*2 < len(ret) && ret[n*2] == -1 {
		dfs1(n*2, count+1)
	}
}

func initBestTimes(n, m int) (int, int) {
	temp := n
	count := 0
	for {
		count++
		temp *= 2
		if temp > m {
			return count + temp - m, temp
		}
	}
}

