import (
	"fmt"
	"sort"
)

const mod = 998244353
const N = 5001

var factor = [N][]int{}
var primes = []int64{}

func comb(m int, n int) int64 {
	for i := len(primes) - 1; i >= 0; i-- {
		if primes[i] <= int64(n) {
			primes = primes[:i+1]
			break
		}
	}
	res := int64(1)
	fnm := make([]int, len(factor[0]))
	copy(fnm, factor[n])
	for i, x := range factor[m] {
		fnm[i] += x
	}
	for w := 1; w <= m; w++ {
		fw, fmw, fnw, r := factor[w], factor[m-w], factor[n-w], int64(1)
		for i, p := range primes {
			for pw := fnm[i] - fw[i] - fmw[i] - fnw[i]; pw > 0; pw >>= 1 {
				if pw&1 == 1 {
					r = r * p % mod
				}
				p = p * p % mod
			}
		}
		res += r
	}
	return res % mod
}

func main() {
	abc := []int{0, 0, 0}
	fmt.Scan(&abc[0], &abc[1], &abc[2])
	sort.Ints(abc)
	a, b, c := abc[0], abc[1], abc[2]
	sieve := [N]bool{true, true}
	for p := range sieve {
		if !sieve[p] {
			primes = append(primes, int64(p))
			for q := p * p; q < N; q += p {
				sieve[q] = true
			}
		}
	}
	for j := range factor {
		factor[j] = make([]int, len(primes))
	}
	for i, p := range primes {
		for pp := p; pp < N; pp *= p {
			for j := pp; j < N; j += pp {
				factor[j][i]++
			}
		}
	}
	cur := factor[2]
	for _, nxt := range factor[3:c+1] {
		for i, x := range cur {
			nxt[i] += x
		}
		cur = nxt
	}
	fmt.Println(comb(b, c) * comb(a, c) % mod * comb(a, b) % mod)
}

