		return
	}
	fmt.Println("NO")
}

func isSolved(data *[6][2][2]int) bool {
	for i := 0; i < 6; i++ {
		if !isSideFull(data, i) {
			return false
		}
	}
	return true
}

func rotate0(data *[6][2][2]int, dir int, sides []int) {
	var nums [4][2]int
	for i := 0; i < len(sides); i++ {
		side := sides[i]
		for j := 0; j < 2; j++ {
			nums[i][j] = data[side][j][0]
		}
	}
	for i := 0; i < len(sides); i++ {
		side := sides[(i+dir+4)%4]
		for j := 0; j < 2; j++ {
			data[side][j][0] = nums[i][j]
		}
	}
}

func isSideFull(data *[6][2][2]int, side int) bool {
	color := data[side][0][0]
	for i := 0; i < 2; i++ {
		for j := 0; j < 2; j++ {
			if data[side][i][j] != color {
				return false
			}
		}
	}
	return true
}

