func swap(a []int, i int, j int) {
    a[i], a[j] = a[j], a[i]
}

func reverse(a []int, i int, j int) {
    for i < j {
        swap(a, i, j)
        i++
        j--
    }
}

func nextPermutation(a []int) bool {
    k := len(a) - 2
    for k > -1 && a[k] > a[k + 1] { k-- }
    if k == -1 { return false }
    l := len(a) - 1
    for k < l && a[k] > a[l] { l-- }
    swap(a, k, l)
    reverse(a, k + 1, len(a) - 1)
    return true
}

func f(a []int) int {
    n := len(a)
    sum := 0
    for i := 0; i < n; i++ {
        for j := i; j < n; j++ {
            min := -1;
            for k := i; k <= j; k++ {
                if min == -1 || min > a[k] {
                    min = a[k]
                }
            }
            sum += min
        }
    }
    return sum
}

