func max(x, y int) int {
	if x > y {
		return x
	}
	return y
}

func consec(arr []int) int {

	ans := 0

	for i := 0; i < len(arr); i++ {
		cur := 1
		last := arr[i]
		for j := i + 1; j < len(arr); j++ {
			if arr[j] == last+1 {
				last = last + 1
				cur++
			} else {
				ans = max(ans, cur)
				break
			}
		}
		ans = max(ans, cur)
	}
	return ans
}

func same(arr []int) int {

	ans := 0

	for i := 0; i < len(arr); i++ {
		cur := 1
		last := arr[i]
		for j := i + 1; j < len(arr); j++ {
			if arr[j] == last {
				cur++
			} else {
				ans = max(ans, cur)
				break
			}
		}
		ans = max(ans, cur)
	}
	return ans
}

