func countDivisor(a, b int) int {
	q := a - b
	ret := 0
	sqrtQ := int(math.Sqrt(float64(q)))
	for i := 1; i < sqrtQ; i++ {
		if q%i != 0 || q/i < b {
			continue
		}
		ret++
		if i <= b {
			continue
		}
		ret++
	}
	if sqrtQ > b && sqrtQ*sqrtQ == q {
		ret++
	}
	return ret
}

