func main() {
	var a, b, f, k int
	fmt.Scanf("%d", &a)
	fmt.Scanf("%d", &b)
	fmt.Scanf("%d", &f)
	fmt.Scanf("%d", &k)

	//fmt.Printf("%v %v %v %v\n", a, b, f, k)

	if (f > b) {
		fmt.Printf("-1")
		return
	}

	if ((k > 1) && (2*(a-f) > b)) {
		fmt.Printf("-1")
		return
	}

	if ((k > 2) && (2*f > b)) {
		fmt.Printf("-1")
		return
	}

	totalCount := 0
	b_current := b
	k0 := 0
	for {
		//forward
		b_current -= f
		if (k0 != k-1) {
			if (((b_current - 2*(a-f)) < 0) || (b_current == 0)) {
				b_current = b
				totalCount++
			}
		} else {
			if (((b_current - (a-f)) < 0) || (b_current == 0)) {
				b_current = b
				totalCount++
			}
		}
		k0++
		if (k0 == k) {
			fmt.Printf("%v", totalCount)
			return
		}
		b_current -= (a-f)
		//backward
		b_current -= (a-f)
		if (k0 != k-1) {
			if ((b_current == 0) || ((b_current - 2*f) < 0)) {
				b_current = b
				totalCount++
			}
		} else {
			if ((b_current == 0) || ((b_current - f) < 0)) {
				b_current = b
				totalCount++
			}
		}
		k0++
		if (k0 == k) {
			fmt.Printf("%v", totalCount)
			return
		}
		b_current -= f
	}
}

