import ("fmt"; "bufio"; "os"; "strings")


func groups(line string) ([]string, []string) {
    outside, inside := make([]string, 0, 10), make([]string, 0, 10)
    parts := strings.FieldsFunc(line, func(c rune) bool {
        return c=='(' || c==')'
    })
    out := line[0]!='('
    for _, p := range parts {
        if out { 
            outside = append(outside, strings.Split(p, "_") ...)
        } else {
            inside = append(inside, strings.Split(p, "_") ...)
        }
        out = !out
    }

    return outside, inside

}


func main() {
    inp := bufio.NewReader(os.Stdin)
    scanner := bufio.NewScanner(inp)

    scanner.Scan() // number
    scanner.Scan()
    outside, inside := groups(scanner.Text())

    fmt.Fprintf(os.Stderr, "%v - %v \n", outside, inside)

    longestOutside := 0
    for _, w := range outside {
        if len(w) > longestOutside {
            longestOutside = len(w)
        }
    }

    inParenthesis := 0
    for _, w := range inside {
        if len(w) > 0 {
            inParenthesis++
        }
    }

    fmt.Println(longestOutside, inParenthesis)
}

