func main() {
	fsc := NewFastScanner()
	n := fsc.NextInt()
	text := fsc.Next()
	var flag, maxLength, inLength, outLength, count int
	for i := 0; i < n; i++ {
		if text[i] == '(' {
			if maxLength < outLength {
				maxLength = outLength
			}
			outLength = 0
			flag = 1
		} else if text[i] == ')' {
			if inLength != 0 {
				count++
			}
			inLength = 0
			flag = 0
		} else if text[i] == '_' {
			if inLength != 0 {
				count++
			}
			inLength = 0
			if outLength != 0 {
				if maxLength < outLength {
					maxLength = outLength
				}
			}
			outLength = 0
		} else if flag == 0 {
			outLength++
		} else if flag == 1 {
			inLength++
		}
	}

	fmt.Println(maxLength, count)
}

