type Cell int

const (
	EmptyCell Cell = iota
	PigCell
	WolfCell
)

func main() {
	s := bufio.NewScanner(os.Stdin)
	s.Split(bufio.ScanWords)
	n := nextInt(s)
	m := nextInt(s)
	gs := make([][]Cell, n)
	wolves := make([]Wolf, 0, n)
	for i := 0; i < len(gs); i++ {
		gs[i] = make([]Cell, m)
		s.Scan()
		row := s.Text()
		for j := 0; j < m; j++ {
			switch row[j] {
			case 'P':
				gs[i][j] = PigCell
			case 'W':
				gs[i][j] = WolfCell
				wolves = append(wolves, Wolf{i, j})
			default:
				gs[i][j] = EmptyCell
			}
		}
	}

	fmt.Println(solve(gs, wolves, len(wolves)-1))
}

func solve(gs [][]Cell, wolves []Wolf, k int) int {
	if k < 0 {
		return 0
	}

	i := wolves[k].i
	j := wolves[k].j

	a, b, c, d, e := 0, 0, 0, 0, 0
	if ix(gs, i-1, j) == PigCell {
		hs := copyGrid(gs)
		hs[i-1][j] = EmptyCell
		hs[i][j] = EmptyCell
		a = 1 + solve(hs, wolves, k-1)
	}
	if ix(gs, i+1, j) == PigCell {
		hs := copyGrid(gs)
		hs[i+1][j] = EmptyCell
		hs[i][j] = EmptyCell
		b = 1 + solve(hs, wolves, k-1)
	}
