const (
	mod = 1000000007
)

func pow(n int, k int) int {
	if k == 0 {
		return 1
	}
	res := pow(n, k>>1)
	res = int((int64(res) * int64(res)) % mod)
	if k&1 != 0 {
		res = int((int64(res) * int64(n)) % mod)
	}
	return res
}

func solve(n int) int {
	a := pow(3, 3*n)
	a -= pow(7, n)
	a %= mod
	if a < 0 {
		return a - mod
	}
	return a
}

func main() {
	var n int
	fmt.Scanf("%d", &n)
	fmt.Println(solve(n))
}

