func factorize(x int64) (length int, result [50]int64) {
    ri:=0
    reminder:=x
    lastdivider:=int64(2)
    for 1<reminder {
        reminderisprime:=true
        for i:=lastdivider; i*i<=reminder; i++ {
            if reminder%i==0 {
                result[ri]=i
                ri++
                reminder/=i
                lastdivider=i
                reminderisprime=false
                break
            }
        }
        if reminderisprime {
            result[ri]=reminder
            break
        }
    }
    return ri,result
}

func convolute(lng int, x [50]int64) (length int,primes,powers,quotients [15]int64) {
    for i:=0; i<=lng; i++ {
        if x[i]==0 {return}
        if i==0||primes[length-1]!=x[i] {
            primes[length]=x[i]
            quotients[length]=x[i]
            length++
        } else {
            quotients[length-1]*=x[i]
        }
        powers[length-1]++
    }
    return
}

