var (
	n, b int64
)

func main() {
	n, b = ReadInt64_2()

	if n == 1 {
		fmt.Println(0)
		return
	}

	memo := TrialDivision(b)

	counts := make(map[int64]int64)
	for a := range memo {
		cnt := int64(0)
		cur := a
		for n/cur != 0 {
			cnt += n / cur

			cur *= a
		}

		counts[a] = cnt
	}

	ans := int64(INF_INT64)
	for a, cnt := range counts {
		e := memo[a]
		ChMin(&ans, cnt/e)
	}
	fmt.Println(ans)
}

// ChMin accepts a pointer of integer and a target value.
// If target value is SMALLER than the first argument,
//	then the first argument will be updated by the second argument.
func ChMin(updatedValue *int64, target int64) bool {
	if *updatedValue > target {
		*updatedValue = target
		return true
	}
	return false
}

// TrialDivision returns the result of prime factorization of integer N.
func TrialDivision(n int64) map[int64]int64 {
	var i, exp int64
	p := map[int64]int64{}

	if n <= 1 {
		panic(errors.New("[argument error]: TrialDivision only accepts a NATURAL number"))
	}

	for i = 2; i*i <= n; i++ {
		exp = 0
		for n%i == 0 {
			exp++
			n /= i
		}

		if exp == 0 {
			continue
		}
		p[i] = exp
	}
	if n > 1 {
		p[n] = 1
	}

	return p
}

