// Node -> node in Linked-List
type Node struct {
	D    int
	Next *Node
}

// Head -> head of Linked-List
type Head struct {
	Front *Node
	Back  *Node
	C     int
}

func (h *Head) createNode(i int) *Node {
	var n *Node = new(Node)
	n.D = i
	n.Next = nil
	h.C++
	return n
}

func (h *Head) solve() int {
	var c int
	h.Back = h.Front
	for i := 0; i < h.C-1; i++ {
		if (h.Back.Next.D - h.Back.D) == 1 {
			c++
		} else if (h.Back.Next.D - h.Back.D) == 2 {
			c += 2
		} else {
			c++
		}
		h.Back = h.Back.Next
	}
	c++

	return c
}

func (h *Head) free() {
	h.Back = h.Front
	for h.Back != nil {
		h.Front = h.Back.Next
		h.Back.D = 0
		h.Back.Next = nil
		h.Back = h.Front
	}
	h.C = 0
}

