import "bufio"
import "strconv"
import "os"
import "container/heap"

const inf = int64(100000000000000000)

type Item struct {
	value    int
	priority int64
	index    int
}

type PriorityQueue []*Item

func (pq PriorityQueue) Len() int { return len(pq) }

func (pq PriorityQueue) Less(i, j int) bool {
	return pq[i].priority < pq[j].priority
}

func (pq PriorityQueue) Swap(i, j int) {
	pq[i], pq[j] = pq[j], pq[i]
	pq[i].index = i
	pq[j].index = j
}

func (pq *PriorityQueue) Push(x interface{}) {
	n := len(*pq)
	item := x.(*Item)
	item.index = n
	*pq = append(*pq, item)
}

func (pq *PriorityQueue) Pop() interface{} {
	old := *pq
	n := len(old)
	item := old[n-1]
	item.index = -1 // for safety
	*pq = old[0 : n-1]
	return item
}

var in *bufio.Scanner
var out *bufio.Writer

func main() {
	in = bufio.NewScanner(os.Stdin)
	out = bufio.NewWriter(os.Stdout)

	in.Split(bufio.ScanWords)
	defer out.Flush()

	in.Scan()
	n, _ := strconv.Atoi(in.Text())

	in.Scan()
	x, _ := strconv.Atoi(in.Text())

	in.Scan()
	y, _ := strconv.Atoi(in.Text())

	best := make([]int64, n*2+1)
	fixed := make([]bool, n*2+1)
	for i := 0; i <= n*2; i++ {
		best[i] = inf
		fixed[i] = false
	}

	root := 0
	best[root] = 0

	var queue PriorityQueue
	queue = append(queue, &Item{value: root, priority: best[root], index: 0})
	heap.Init(&queue)

	for queue.Len() > 0 {
		item := heap.Pop(&queue).(*Item)
		u := item.value

		if !fixed[u] {
			fixed[u] = true
			delta := []int{u - 1, u + 1, u * 2}
			cost := []int{x, x, y}
			for idx, v := range delta {
				if (v > 0) && (v <= 2*n) && (!fixed[v]) {
					cost := int64(cost[idx])
					if best[v] > best[u]+cost {
						best[v] = best[u] + cost
						newItem := &Item{value: v, priority: best[v]}
						heap.Push(&queue, newItem)
					}
				}
			}
		}
	}

	out.WriteString(strconv.FormatInt(best[n], 10))
	out.WriteByte('\n')
}

