func dp(n int, x int64, y int64) int64 {
	f := make([]int64, n+1)

	f[0] = 0
	for i := 1; i <= n; i++ {
		if i%2 == 0 {
			f[i] = min(f[i-1]+x, f[i/2]+y)
		} else {
			f[i] = min(f[i-1]+x, f[(i+1)/2]+y+x)
		}
	}

	return f[n]
}

