	for _, x := range xs {
		sum += x
	}
	sort.Sort(Foo(xs))
	ans := int64(0)
	for i := 0; i < n; i++ {
		altm := sum * int64(i)
		if altm > m {
			break
		}
		tmp := int64((k + 1) * i)
		p := int64(n - i)
		for _, x := range xs {
			w := p
			for altm+w*x > m {
				w--
			}
			altm += w * x
			tmp += w
		}
		if tmp > ans {
			ans = tmp
		}
	}
	fmt.Println(ans)
}

