func rem(x int64) int64 {
    var rr, r int64
    for x > int64(0) {
        if x%10 != 0 {
            rr *= 10
            rr += x % 10
        }
        x /= 10
    }

    r = 0
    for rr > int64(0) {
        r *= 10
        r += rr % 10
        rr /= 10
    }
    return r
}

