func I(i interface{}, delim string) error {
	_, err := fmt.Fscanf(r, "%v"+delim, i)
	return err
}

func O(o interface{}, delim string) {
	fmt.Fprintf(w, "%v"+delim, o)
}

var (
	r *bufio.Reader
	w *bufio.Writer
)

func init() {
	if f, err := os.Open("in.txt"); err == nil {
		r = bufio.NewReader(f)
	} else {
		r = bufio.NewReader(os.Stdin)
	}
	w = bufio.NewWriter(os.Stdout)
}

func main() {
	defer w.Flush()
	var n int
	for I(&n, " ") == nil {
		solve(n)
	}
}

func solve(n int) {
	var m int
	I(&m, "\n")
	max := int64(n - (m - 1))
	min := int64(n / m)
	if n%m == 0 {
		min = C(int(min)) * int64(m)
	} else {
		min = C(int(min))*int64(m-1) + C(int(min)+n%m)
	}
	max = C(int(max))
	O(min, " ")
	O(max, "\n")
}

func C(a int) int64 {
	return int64(a) * int64(a-1) / int64(2)
}

