func f(cs []int) int {
	gs := graphs(cs)

	if len(gs) == 0 {
		return -1
	}

	if len(gs) == 1 {
		return gs[0]
	}

	for i, g := range gs {
		if g%2 == 0 {
			gs[i] = g / 2
		}
	}

	return lcmm(gs...)
}

func graphs(cs []int) []int {
	seen := make(map[int]bool, len(cs))

	var ls []int

	for j, c := range cs {
		i := j + 1

		if seen[i] {
			continue
		}

		if cs[i-1] == i {
			seen[i] = true
			seen[cs[i-1]] = true
			ls = append(ls, 1)
			continue
		}

		l := 2

		for ; ; l++ {
			seen[c] = true
			next := cs[c-1]
			if next == i {
				break
			}
			if seen[next] {
				return nil
			}
			c = next
		}
		seen[i] = true
		ls = append(ls, l)
	}
	return ls
}

func gcd(a, b int) int {
	for b > 0 {
		a, b = b, a%b
	}
	return a
}

func lcm(a, b int) int {
	return a * b / gcd(a, b)
}

func lcmm(xs ...int) int {
	r := 1
	for _, x := range xs {
		r = lcm(r, x)
	}
	return r
}

