func solve(a int) {
	var in [3][3]int
	in[0][0] = a
	for i := 0; i < 3; i++ {
		for j := 0; j < 3; j++ {
			if i != 0 || j != 0 {
				o := " "
				if j == 2 {
					o = "\n"
				}
				I(&in[i][j], o)
			}
		}
	}
	var x [3][3]int
	for i := 0; i < 3; i++ {
		for j := 0; j < 3; j++ {
			x[i][j] = 1
		}
	}
	for i := 0; i < 3; i++ {
		for j := 0; j < 3; j++ {
			for in[i][j] > 0 {
				x[i][j] ^= 1
				for ii := 0; ii < 3; ii++ {
					if ii != i && ii != j {
						x[ii][j] ^= 1
						x[i][ii] ^= 1
					}
				}
				in[i][j]--
			}
		}
	}
	for i := 0; i < 3; i++ {
		for j := 0; j < 3; j++ {
			O(x[i][j], "")
		}
		O("", "\n")
	}
}

