)

const GRID_SIZE = 3

type Grid [][]bool

func main() {
	grid := createSquareGrid(GRID_SIZE)
	for i := 0; i < GRID_SIZE; i++ {
		for j := 0; j < GRID_SIZE; j++ {
			var n int
			fmt.Fscan(os.Stdin, &n)
			grid.toggleNTimes(i, j, n)
		}
	}
	fmt.Print(grid)
}

func createSquareGrid(size int) Grid {
	grid := make(Grid, size)
	for rowIdx := range grid {
		grid[rowIdx] = make([]bool, size)
		for colIdx := range grid[rowIdx] {
			grid[rowIdx][colIdx] = true
		}
	}
	return grid
}

func (grid Grid) toggleNTimes(i, j, n int) {
	if n <= 0 { return }
	toggle := func(i, j int) { grid[i][j] = !grid[i][j] }
	toggle(i, j)
	n = n % 2
	if (n > 0) {
		if i > 0 { toggle(i-1, j) }
		if j > 0 { toggle(i, j-1) }
		if i < GRID_SIZE-1 { toggle(i+1, j) }
		if j < GRID_SIZE-1 { toggle(i, j+1) }
	}
}

func (grid Grid) String() string {
	var buffer bytes.Buffer
	for rowIdx := range grid {
		buffer.WriteString(boolAsString(grid[rowIdx][0]))
		for colIdx := 1; colIdx < len(grid[rowIdx]); colIdx++ {
			buffer.WriteString(boolAsString(grid[rowIdx][colIdx]))
		}
		buffer.WriteString("\n")
	}
	return buffer.String()
}

func boolAsString(b bool) string {
	if b { return "1" }
	return "0"
}

