func checkVertical(table [][]rune) bool {
	for i := 0; i < size; i++ {
		if table[i][0] == x && table[i][1] == x && table[i][2] == x {
			return true
		}

		if table[i][1] == x && table[i][2] == x && table[i][3] == x {
			return true
		}
	}

	return false
}

func checkHorizontal(table [][]rune) bool {
	for j := 0; j < size; j++ {
		if table[j][0] == x && table[j][1] == x && table[j][2] == x {
			return true
		}

		if table[j][1] == x && table[j][2] == x && table[j][3] == x {
			return true
		}
	}

	return false
}

func checkDiagonal(table [][]rune) bool {
	for i := 0; i < size; i++ {
		for j := 0; j < size; j++ {
			var ii, jj int

			ii = i + 2
			jj = j + 2

			if ii < size && jj < size && table[i][j] == x && table[i+1][j+1] == x && table[i+2][j+2] == x {
				return true
			}

			ii = i + 2
			jj = j - 2

			if ii < size && jj >= 0 && table[i][j] == x && table[i+1][j-1] == x && table[i+2][j-2] == x {
				return true
			}
		}
	}

	return false
}

