var n, m, k int64

func solve(n int64) {
	I(&m, " ")
	I(&k, "\n")
	p := k - (n - k)
	o := (k * (k + 1) / 2) + (k*(k-1))/2 - (p * (p - 1) / 2)
	ans := k
	if o < m {
		ans += (m - o) / n
	} else if o > m {
		ans -= (o-m)/n + 1
	}
	O(ans, "\n")
}

