var n, m, k int64

func solve(n int64) {
	I(&m, " ")
	I(&k, "\n")
	p := k - (n - k)
	o := (k * (k + 1) / 2) + (k*(k-1))/2 - (p * (p - 1) / 2)
	ans := k
	if o < m {
		for o+n <= m {
			o += n
			ans++
		}
	} else if o > m {
		var q int64
		for o >= m {
			o--
			if q == 0 || q == n {
				ans--
				q = 0
			}
			q++
		}
	}
	O(ans, "\n")
}

