func solve() {
	people := readInt()
	pillow := readInt()
	k := readInt()
	if people == 1 {
		fmt.Println(pillow)
		return
	}
	pillow -= people
	left := int64(k - 1)
	right := int64(people - k)
	lo := 0
	hi := pillow
	best := 0
	for lo <= hi && pillow > 0 {
		mi := lo + (hi-lo)/2
		rest := int64(pillow - mi)
		step := int64(mi - 1)
		var sum1 int64
		var sum2 int64
		if left > 0 && step > 0 {
			if step < left {
				left = step
			}
			sum1 = int64(step-left+1+step) * left / 2
		}
		if right > 0 && step > 0 {
			if step < right {
				right = step
			}
			sum2 = int64(step-right+1+step) * right / 2
		}
		if sum1+sum2 <= rest {
			lo = mi + 1
			if best < mi {
				best = mi
			}
		} else {
			hi = mi - 1
		}
	}
	fmt.Println(best + 1)
}

