func min(x, y int64) int64 {
	if x < y {
		return x
	}
	return y
}

func Solve(n int, L int64, c []int64) int64 {
	for i := 1; i < n; i++ {
		if c[i] > 2*c[i-1] {
			c[i] = 2 * c[i-1]
		}
	}
	ans := int64(math.MaxInt64)
	sum := int64(0)
	for i := n - 1; i >= 0; i-- {
		liters := int64(1 << i)
		if liters <= L {
			bottles := L / liters
			L -= bottles * liters
			sum += bottles * c[i]
		} else {
			ans = min(ans, sum+c[i])
		}
	}
	return min(ans, sum)
}

func main() {
	reader := bufio.NewReader(os.Stdin)
	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	var n int
	var L int64
	fmt.Fscanf(reader, "%d %d\n", &n, &L)
	c := make([]int64, n)
	for i := 0; i < n; i++ {
		fmt.Fscanf(reader, "%d", &c[i])
	}
	fmt.Fscanf(reader, "\n")

	fmt.Fprintf(writer, "%d\n", Solve(n, L, c))
}

