func makeHappy(values []int) int {
	n := 3
	sumA, sumB := 0, 0
	for i := 0; i < n; i++ {
		sumA += values[i]
		sumB += values[n + i]
	}

	if sumA == sumB {
		return 0
	}

	diff := sumA - sumB

	for i := 0; i < n; i++ {
		a := values[i] - diff
		if a > 0 && a <= 9 {
			return 1
		}
		a = values[n + i] + diff
		if a > 0 && a <= 9 {
			return 1
		}
	}

	valsA := values[:n]
	valsB := values[n:]
	sort.Ints(valsA)
	sort.Ints(valsB)

	if diff > 0 {
		diff -= valsA[2]
		valsA[2] = 0

		diff -= 9 - valsB[0]
		if diff < 0 {
			return 2
		}

		return 3
	}

	diff += valsB[2]
	valsB[2] = 0

	diff += 9 - valsA[0]
	if diff > 0 {
		return 2
	}

	return 3
}

