func get_weight(piece byte) int {
    reverse := false
    if piece >= 'a' && piece <= 'z' {
        reverse = true
        piece = piece - 'a' + 'A'
    }

    ret := 0
    switch piece {
        case 'Q':
            ret = 9
        case 'R':
            ret = 5
        case 'B':
            ret = 3
        case 'K':
            ret = 3
        case 'P':
            ret = 1
    }

    if reverse {
        return -ret
    }
    return ret
}

