var stdReader *bufio.Reader = bufio.NewReader(os.Stdin)

func readInt() (result int) {
	var negative, started bool
READER_LOOP:
	for {
		char, err := stdReader.ReadByte()
		switch {
		case err != nil:
			break READER_LOOP
		case char == '-':
			negative = true
		case unicode.IsDigit(rune(char)):
			started = true
			result = result*10 + int(char&0xf)
		case started:
			break READER_LOOP
		}
	}
	if negative {
		result = -result
	}
	return
}

func main() {
	n := readInt()

	// dp[][0] - Vasya rested
	// dp[][1] - Vasya wrote contest
	// dp[][2] - Vasya practiced in a gym
	dp := make([][3]int, n+1)
	for i := 1; i <= n; i++ {
		// dp[i][0]
		dp[i][0] = dp[i-1][0]
		if dp[i-1][1] > dp[i][0] {
			dp[i][0] = dp[i-1][1]
		}
		if dp[i-1][2] > dp[i][0] {
			dp[i][0] = dp[i-1][2]
		}

		input := readInt()
		// dp[i][1]
		if input == 1 || input == 3 {
			dp[i][1] = dp[i-1][0]
			if dp[i-1][2]+1 > dp[i][1] {
				dp[i][1] = dp[i-1][2] + 1
			}
		}

		// dp[i][2]
		if input == 2 || input == 3 {
			dp[i][2] = dp[i-1][0]
			if dp[i-1][1]+1 > dp[i][2] {
				dp[i][2] = dp[i-1][1] + 1
			}
		}
	}

	answer := dp[n][0]
	if dp[n][1] > answer {
		answer = dp[n][1]
	}
	if dp[n][2] > answer {
		answer = dp[n][2]
	}
	fmt.Println(n - answer)
}

