func Solve(na int32, nb int32, current int32) int {
  if na == 0 && nb == 0 {
    return 0;
  }

  var r0 int = 1000;
  var r1 int = 1000;
  var r2 int = 1000;

  if 0 < na && a <= current {
    r0 = Solve(na - 1, nb, current - a);
  }
  if 0 < nb && b <= current {
    r1 = Solve(na, nb - 1, current - b);
  }
  if current < a && current < b {
    r2 = 1 + Solve(na, nb, n);
  }
  result := r0
  if r1 < result {
    result = r1
  }
  if r2 < result {
    result = r2
  }

  return result
}

