func bis(num int) int {
	l := 1
	r := num
	for l <= r {
		mid := (l + r) >> 1
		if mid*(mid+1)/2 > num {
			r = mid - 1
		} else {
			l = mid + 1
		}
	}
	return r
}

func solve() {
	m := bis(n)
	if n == m*(m+1)/2 {
		Println(m)
	} else {
		Println(n - m*(m+1)/2)
	}
}

