const MOD = 998244353
const LCM16 = 720720 // lcm(1, 2, 3, ..., 16)
const MAXK = 17

func add(a, b int) int {
	return (a + b) % MOD
}

func mul(a, b int) int {
	return int(int64(a) * int64(b) % MOD)
}

func fpow(b, e int) int {
	r := 1
	for ; e > 0; e >>= 1 {
		if (e & 1) > 0 {
			r = mul(r, b)
		}
		b = mul(b, b)
	}
	return r
}

func inv(a int) int {
	return fpow(a, MOD-2)
}

var dp [MAXK + 1][LCM16]int

var prob0 int
var prob1 int

func calcDP(maxK int) {
	if maxK < 2 {
		return
	}
	for k := maxK; k >= 2; k-- {
		for r := 0; r < LCM16; r++ {
			dp[k][r] = add(
				mul(prob0, dp[k+1][r]),
				mul(prob1, add(dp[k+1][r-r%k], r%k)),
			)
		}
	}
}

func main() {
	defer flush()

	var n, a0, k, ai int
	var genX, genY, genMod int64
	scan(&n, &a0, &genX, &genY, &k, &genMod)

	ninv := inv(n)
	prob0 = mul(n-1, ninv)
	prob1 = ninv

	ans := 0
	for j := 1; j <= k; j++ {
		calcDP(j - 1)

		ai = a0
		for i := 0; i < n; i++ {
			ans = add(ans, mul(prob1, add(ai, MOD-dp[2][ai%LCM16])))
			ai = int((int64(ai)*genX + genY) % genMod)
		}
	}

	printf("%d\n", mul(ans, fpow(n, k)))
}

