	x, steps int64
}

func main() {
	io := NewIO(os.Stdin, os.Stdout)
	nm := io.ReadIntSlice(2)

	stack := make([]pair, 0)
	stack = append(stack, pair{x: nm[1], steps: 0})
	used := make(map[int64]struct{})

	mn := int64(1e9)
	done := false

	s := 0
	for len(stack) > 0 {
		s++
		//if s%1000000 == 0 {
		//	fmt.Println(stack)
		//}
		//fmt.Println(len(stack), mn)
		last := stack[len(stack)-1]
		//fmt.Println(last.x)
		stack = stack[:len(stack)-1]

		var currentLen int64 = 0
		nums := make([]bool, 10)

		currentX := last.x
		for currentX != 0 {
			num := currentX % 10
			currentX /= 10
			currentLen++
			if !nums[num] {
				nums[num] = true
			}
		}

		//fmt.Println(nums)

		if currentLen == nm[0] {
			done = true
			mn = min(mn, last.steps)
		} else {
			for i := int64(9); i >= 2; i-- {
				if nums[i] {
					next := last.x * i
					//fmt.Println("next", next)
					if next < last.x {
						continue
					}
					if _, ok := used[next]; ok {
						continue
					}
					if last.steps >= nm[0]+5 {
						continue
					}
					stack = append(stack, pair{x: next, steps: last.steps + 1})
				}
			}
		}
	}

	if !done {
		fmt.Println(-1)
	} else {
		fmt.Println(mn)
	}
}

