func main() {
	r := bufio.NewReader(os.Stdin)
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()

	var p1, t1, p2, t2, h, s int
	fmt.Fscan(r, &p1, &t1, &p2, &t2, &h, &s)

	dp := make([]int, h+1)
	for i := range dp {
		if i == 0 { continue }
		dp[i] = min(t1 + dp[max(0, i - (p1-s))], t2 + dp[max(0, i - (p2-s))])
		for j := 1; j <= i; j++ {
			if j*t1 >= t2 { dp[i] = min(dp[i], j*t1 + dp[max(0, i - j*(p1-s) - p2)]) }
			if j*t2 >= t1 { dp[i] = min(dp[i], j*t2 + dp[max(0, i - j*(p2-s) - p1)]) }
		}
	}

	fmt.Fprintln(w, dp[h])
}

