	} else {
		return j;
	}
}
const (
	INF64 = int64(1e18)
)
func solve(_r io.Reader, _w io.Writer) {
	in := bufio.NewReader(_r)
	out := bufio.NewWriter(_w)

	defer out.Flush()

	p := [2]int64{}
	t := [2]int64{}
	Fscan(in, &p[0], &t[0], &p[1], &t[1])

	var h, s int64
	Fscan(in, &h, &s)

	dp := make([]int64, h+1)
	for i := range dp {
		dp[i] = INF64
	}
	dp[0] = 0
	ans := INF64

	for i := int64(0); i <= h; i++ {
		for j := int64(1); j <= h - i; j++ {
			for k := 0; k < 2; k++ {
				ni := min(h, i + j*(p[k]-s) + j*t[k]/t[k^1]*(p[k^1]-s))
				if ni == h {
					ans = min(ans, dp[i] + j*t[k])
				}
				if j*t[k] >= t[k^1] {
					ni = min(h, i + (j-1)*(p[k]-s) + (j-1)*t[k]/t[k^1]*(p[k^1]-s) + (p[0]+p[1]-s))
					dp[ni] = min(dp[ni], dp[i] + j*t[k])
				}
			}
		}
	}
	ans = min(ans, dp[h])
	Fprintln(out, ans)
}
