func do(n, k int) int64 {
	if k == 0 {
		return 1
	}
	tk := getTk(n, k)
	gr, eq := getGrEq(n)
	r := gr + eq
	for i := 2; i <= k; i++ {
		r = (((eq * r) % mod) + ((gr * tk[i-1]) % mod)) % mod
	}
	return r
}

const mod = 1e9 + 7

func getTn(n int) []int64 {
	tn := make([]int64, n+1)
	tn[0] = 1
	for i := 1; i <= n; i++ {
		tn[i] = (tn[i-1] * 2) % mod
	}
	return tn
}

func getTk(n, k int) []int64 {
	tk := make([]int64, k+1)
	tk[0] = 1
	tn := getTn(n)
	for i := 1; i <= k; i++ {
		tk[i] = (tk[i-1] * tn[n]) % mod
	}
	for i := 1; i <= k; i++ {
		tk[i] = (tk[i] + tk[i-1]) % mod
	}
	return tk
}

func getGrEq(n int) (int64, int64) {
	if n == 1 {
		return 0, 1
	}
	if n == 2 {
		return 1, 1
	}
	tn := getTn(n)
	var gr, eq int64 = 0, tn[n-1]
	if n%2 == 0 {
		gr = 1
	} else {
		eq = (eq + 1) % mod
	}
	return gr, eq
}

