	fmt.Println(dp[n] % internalm)

}

func solve2(n int64, tempCount int64) int64 {
	if n < 1 {
		return 0
	}
	if n == 1 {
		return 1
	}
	if dp[n] != 0 {
		return dp[n]
	}
	var currentAns int64
	for i := 1; i < int(n); i++ {
		currentAns += solve2(n-int64(i), tempCount+1)
	}
	for i := 2; i <= int(n); i++ {
		currentAns += solve2(int64(math.Floor(float64(n/int64(i)))), tempCount+1)
	}
	dp[n] = currentAns
	return currentAns
}

