func do(n int, m int64) int64 {
	d := make([]int64, n+1)
	d[n] = 1
	for i := n; i >= 1; i-- {
		for j := 1; j < i; j++ {
			d[i-j] = (d[i-j] + d[i]) % m
		}
		for j := n; j >= 2; j-- {
			d[i/j] = (d[i/j] + d[i]) % m
		}
	}
	return d[1]
}

