func memoizedCNK(memosize int) func(int, int) int {
	memo := make(map[int]map[int]int)
	for i := 0; i <= memosize; i++ {
		memo[i] = make(map[int]int)
	}
	var cnk func(int, int) int
	cnk = func(n, k int) int {
		if k < 0 || k > n {
			return 0
		}
		if n == 0 || k == 0 || k == n {
			return 1
		}
		val, ok := memo[n][k]
		if !ok {
			val = cnk(n-1, k-1) + cnk(n-1, k)
			memo[n][k] = val
		}
		return val
	}
	return cnk
}

func CNK(n, k int) int {
	if k < 0 || k > n {
		return 0
	}
	if n == 0 || k == 0 || k == n {
		return 1
	}

	return CNK(n-1, k-1) + CNK(n-1, k)

}

func Solve(reader io.Reader, writer io.Writer) {
	var n, k int
	fmt.Fscanf(reader, "%d %d\n", &n, &k)
	cnk := memoizedCNK(n)
	sum := 0
	for ; k >= 0; k-- {
		sum += cnk(n, k) % 1000000007
	}
	fmt.Fprintln(writer, sum)

}

