func ModCombination(n, k int64) (ret int64) {
	if n < k {
		return int64(0)
	}
	for ret = int64(1); n > int64(0) || k > int64(0); n, k = n/Mod, k/Mod {
		ret = ret * fac[n%Mod] % Mod * finv[k%Mod] % Mod * finv[(n-k)%Mod] % Mod
	}
	return
}

const MAX = 5e6

var fac, finv, inv [MAX + 1]int64

func init() {
